/* =========================================================
 DATENSCHUTZ: Erklärung, Datenauskunft/-export, Löschung
 ========================================================= */
const DS_APP="F12Sb";
const DS_HINWEIS_FREITEXT="🔒 Bitte hier keine sensiblen Daten eintragen (Gesundheit, Familie, Religion, Herkunft, Konflikte) – weder über dich noch über andere.";
function dsHinweis(){return`<small class="ds-hinweis"style="display:block;margin:4px 0 8px;color:var(--muted,#5b6b7a)">${DS_HINWEIS_FREITEXT}</small>`}

/* Sammlungen mit personenbezogenen Daten: [Sammlung, Feld, selbst löschbar?]
   "id" = Dokument-ID ist die UID (Abfrage über getDoc). */
const DS_DATEN=[["journal","uid",1],["competencies","uid",1],["lernpfade","uid",1],["resilienzSchaetze","uid",1],["heimatorte","uid",1],["steckbriefe","uid",1],["wochenplanung","uid",1],["noten","id",1],["essayEntries","uid",1],["essayCases","createdBy",1],["ppStundenAntworten","uid",1],["ppLernuebersicht","uid",1],["ppKursFortschritt","uid",1],["ppRallyeStand","uid",1],["ppRallyeRang","uid",1],["lehrplanFortschritt","uid",1],["lernLive","uid",1],["ubErgebnisse","uid",1],["faErgebnisse","uid",1],["lehrplanProdukte","uid",1],["lehrplanTeams","createdBy",1],["messages","fromUid",1],["posts","authorUid",1],["boardPosts","authorUid",1],["tasks","createdBy",1],["projects","createdBy",1],["wordcloudEntries","authorUid",1],["kanbanCards","createdBy",1],["checklistItems","createdBy",1],["termVotes","uid",1],["pollVotes","uid",1],["ampelResponses","uid",1],["teamAds","authorUid",1],["flashcards","createdBy",1],["glossaryEntries","createdBy",1],["whiteboardItems","authorUid",1],["whiteboardImages","authorUid",1],["whiteboardPresence","uid",1],["randomPickerLists","createdBy",1],["profilePublic","id",1],["checkoutAbgaben","uid",0],["checkoutAuswahl","id",0],["lernstandVersuche","uid",0]];
async function dsLesen(uid,c,feld){
 if(feld==="id"){const s=await getDoc(doc(db,c,uid));return s.exists()?[{id:s.id,data:s.data()}]:[]}
 const q=await getDocs(query(collection(db,c),where(feld,"==",uid)));
 return q.docs.map(d=>({id:d.id,data:d.data()}));
}
async function dsSammeln(uid){
 const out={},fehler=[];
 for(const [c,feld] of DS_DATEN){
  try{const l=await dsLesen(uid,c,feld);if(l.length)out[c]=l}catch(e){fehler.push(c)}
 }
 return{out,fehler};
}
async function dsExport(){
 try{
  toast("Daten werden zusammengestellt …");
  const uid=currentUser.uid;
  const {out,fehler}=await dsSammeln(uid);
  let konto=null;try{const s=await getDoc(doc(db,"users",uid));konto=s.exists()?s.data():null}catch(e){}
  const pack={app:DS_APP,exportiertAm:new Date().toISOString(),konto,daten:out,nichtAbrufbar:fehler};
  const blob=new Blob([JSON.stringify(pack,null,2)],{type:"application/json"});
  const a=document.createElement("a");a.href=URL.createObjectURL(blob);
  a.download=`${DS_APP}-meine-daten.json`;document.body.appendChild(a);a.click();
  setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1000);
  toast("Datei „"+DS_APP+"-meine-daten.json“ wurde erstellt.");
 }catch(e){console.error(e);toast("Export nicht möglich.")}
}
/* Löscht die Daten einer Person; gibt {geloescht, gesperrt:[Sammlungen]} zurück. */
async function dsLoeschen(uid,{alsAdmin=false}={}){
 let geloescht=0;const gesperrt=[];
 for(const [c,feld,selbst] of DS_DATEN){
  if(!alsAdmin&&!selbst)continue;
  if(feld==="id"){try{await deleteDoc(doc(db,c,uid))}catch(e){gesperrt.push(c)}continue}
  try{
   const l=await dsLesen(uid,c,feld);
   for(const d of l){try{await deleteDoc(doc(db,c,d.id));geloescht++}catch(e){if(!gesperrt.includes(c))gesperrt.push(c)}}
  }catch(e){if(!gesperrt.includes(c))gesperrt.push(c)}
 }
 return{geloescht,gesperrt};
}
async function dsMeineDatenLoeschen(){
 const t=prompt("Alle deine Daten in der "+DS_APP+" werden endgültig gelöscht (Journal, Pläne, Beiträge, Konto …). Leistungsnachweise (Check-out, Lernstandsmessung) bleiben als schulische Unterlagen bei der Schule.\n\nZur Bestätigung bitte LÖSCHEN eingeben:");
 if(t!=="LÖSCHEN")return;
 try{
  toast("Daten werden gelöscht …");
  const uid=currentUser.uid;
  const r=await dsLoeschen(uid);
  /* Konto zuletzt: erst danach verlieren die Regeln die Freigabe */
  let kontoWeg=false;
  try{await deleteDoc(doc(db,"users",uid));kontoWeg=true}catch(e){console.error(e)}
  try{if(kontoWeg&&auth.currentUser)await deleteUser(auth.currentUser)}catch(e){console.error(e)}
  alert(r.geloescht+" Einträge gelöscht."+(kontoWeg?" Dein Konto wurde entfernt.":" Das Konto konnte nicht entfernt werden – bitte die Lehrkraft informieren.")+(r.gesperrt.length?"\nNicht löschbar: "+r.gesperrt.join(", "):""));
  try{await signOut(auth)}catch(e){}
  location.reload();
 }catch(e){console.error(e);toast("Löschen nicht vollständig möglich.")}
}
async function dsKlasseLoeschen(){
 if(!isAdmin()){toast("Nur Admin.");return}
 const mitKonten=confirm("Schuljahresende: Alle Schüler-Daten dieser App löschen.\n\nOK = Daten UND Konten (Profile) löschen\nAbbrechen = zurück");
 if(!mitKonten)return;
 const t=prompt("Dies kann nicht rückgängig gemacht werden. Bitte vorher die Daten sichern.\nZur Bestätigung KLASSE LÖSCHEN eingeben:");
 if(t!=="KLASSE LÖSCHEN")return;
 try{
  toast("Klasse wird gelöscht – bitte warten …");
  const us=await getDocs(query(collection(db,"users"),where("role","==","student")));
  let n=0,gesperrt=new Set(),personen=0;
  for(const u of us.docs){
   const r=await dsLoeschen(u.id,{alsAdmin:true});n+=r.geloescht;r.gesperrt.forEach(x=>gesperrt.add(x));personen++;
   try{await deleteDoc(doc(db,"users",u.id))}catch(e){gesperrt.add("users")}
  }
  closeModal();
  alert(personen+" Schüler-Konten bearbeitet, "+n+" Einträge gelöscht."+(gesperrt.size?"\n\nNicht per Admin löschbar (privat bzw. nur durch die Person selbst, z. B. Nachrichten, Resilienz-Schatzkiste, Wochenplanung): "+[...gesperrt].join(", ")+"\nDiese Daten sind für niemanden einsehbar; sie lassen sich in der Firebase-Konsole (Firestore) löschen.":"")+"\n\nWichtig: Die Anmeldekonten selbst bitte in der Firebase-Konsole unter Authentication löschen.");
 }catch(e){console.error(e);toast("Löschen nicht vollständig möglich.")}
}
function showDatenschutz(){const e=!!(typeof currentUser<"u"&&currentUser&&typeof profile<"u"&&profile&&profile.status==="approved");modal(`<button class="modal-close"onclick="closeModal()">\xD7</button>
 <div class="kicker">RECHTLICHES</div>
 <h2>Datenschutzerkl\xE4rung</h2>
 <div class="form"style="gap:12px;font-size:.95em;line-height:1.5">
 <div class="notice"><strong>Abgestimmt</strong><p style="margin-bottom:0">Die Nutzung der App ist mit dem Datenschutzbeauftragten der Schule abgestimmt.</p></div>

 <p><strong>1. Verantwortlicher</strong><br>
 Staatliche Fachoberschule und Berufsoberschule Weilheim, Kerschensteinerstra\xDFe 2, 82362 Weilheim i.OB, vertreten durch den Schulleiter Christian Dick, OStD. Telefon +49 881 9239-43, E-Mail 0897.Sekretariat@schule.bayern.de.</p>

 <p><strong>2. Datenschutzbeauftragter</strong><br>
 Niklas Hilber, <a href="mailto:niklas.hilber@schule.bayern.de">niklas.hilber@schule.bayern.de</a></p>

 <p><strong>3. Zweck und Rechtsgrundlage</strong><br>
 Die ${DS_APP}-App unterst\xFCtzt den Unterricht (Lernpl\xE4ne, Lernjournal, \xDCbungen, Check-outs, Zusammenarbeit). Die Verarbeitung erfolgt zur Erf\xFCllung des schulischen Bildungs- und Erziehungsauftrags (Art. 6 Abs. 1 Buchst. e DSGVO i. V. m. Art. 4 BayDSG und Art. 85 BayEUG). Freiwillige Angaben (z. B. Steckbrief, Geburtstag, Herkunftsort) beruhen auf deiner Einwilligung (Art. 6 Abs. 1 Buchst. a DSGVO); du kannst sie jederzeit l\xF6schen oder widerrufen.</p>

 <p><strong>4. Welche Daten werden verarbeitet?</strong></p>
 <ul style="margin:0 0 0 18px">
 <li>Konto: selbst gew\xE4hltes Pseudonym (kein Klarname, keine E-Mail-Adresse), Rolle und Freigabestatus, Anmeldezeitpunkt</li>
 <li>Lern- und Arbeitsdaten: Lernjournal, Lernpfad, Kompetenzen, Wochenplanung, \xDCbungs- und Aufsatztexte, Antworten in Check-outs und Lernstandsmessungen, Selbsteinsch\xE4tzungen bei Fachaufsatz-\xDCbungen (nur Punktzahlen, ohne deinen Text), Fortschritte, abgegebene Dateien</li>
 <li>Zusammenarbeit: Beitr\xE4ge, Nachrichten, Pinnwand, Whiteboards, Umfragen und Abstimmungen</li>
 <li>Freiwillig: Steckbrief, Geburtstag (Tag und Monat), Herkunftsort</li>
 <li>Technisch: IP-Adresse und Ger\xE4teinformationen bei jedem Aufruf (siehe Punkt 5)</li>
 </ul>
 <p>Bitte trage keine sensiblen Daten (Gesundheit, Familie, Religion, Herkunft, Konflikte) in Freitextfelder ein.</p>

 <p><strong>5. Empf\xE4nger und Dienstleister</strong><br>
 <em>Google Firebase</em> (Google Cloud EMEA Limited / Google LLC): Anmeldung, Datenbank (Firestore) und Dateispeicher. Die Daten werden in einem Rechenzentrum von Google gespeichert; eine Verarbeitung durch das US-Unternehmen Google LLC ist dabei nicht ausgeschlossen. Grundlage der \xDCbermittlung sind der Angemessenheitsbeschluss zum EU-US Data Privacy Framework bzw. Standardvertragsklauseln.<br>
 <em>GitHub Pages</em> (GitHub Inc., Microsoft): Auslieferung der Webseite. Dabei wird deine IP-Adresse verarbeitet.<br>
 <em>Eingebettete Inhalte</em> (YouTube, Vimeo, WebUntis): Erst wenn du solche Inhalte \xF6ffnest, wird eine Verbindung zum jeweiligen Anbieter aufgebaut und deine IP-Adresse \xFCbermittelt.<br>
 Die Software der App wird von dieser Seite selbst ausgeliefert, es werden keine Schriftarten, Tracker oder Werbedienste von Dritten geladen.</p>

 <p><strong>6. Cookies und lokaler Speicher</strong><br>
 Die App setzt keine Tracking-Cookies. Im Browser werden nur Einstellungen gespeichert (z. B. Ansichtsgr\xF6\xDFe) sowie die technisch n\xF6tige Anmeldung.</p>

 <p><strong>7. Speicherdauer</strong><br>
 Deine Daten werden gel\xF6scht, wenn du die Klasse verl\xE4sst, sp\xE4testens zum Ende des Schuljahres. Du kannst deine Daten jederzeit selbst l\xF6schen (siehe unten). Leistungsnachweise (Check-outs, Lernstandsmessungen) werden nach den schulrechtlichen Aufbewahrungsfristen als Unterlagen der Schule behandelt.</p>

 <p><strong>8. Wer sieht was?</strong><br>
 Lehrkr\xE4fte sehen deine Lern- und Arbeitsdaten sowie Abgaben und sehen live, an welchem Thema und in welchem Lernschritt du gerade arbeitest. Mitsch\xFCler:innen sehen nur, was du in gemeinsamen Bereichen (Forum, Pinnwand, Whiteboard, Steckbrief) ver\xF6ffentlichst. Wochenplanung, Resilienz-Schatzkiste und Nachrichten sind f\xFCr Lehrkr\xE4fte nicht einsehbar. Der Notenrechner speichert nichts.</p>

 <p><strong>9. Deine Rechte</strong><br>
 Auskunft (Art. 15), Berichtigung (Art. 16), L\xF6schung (Art. 17), Einschr\xE4nkung (Art. 18), Daten\xFCbertragbarkeit (Art. 20) und Widerspruch (Art. 21 DSGVO). Wende dich dazu an die Schule oder den Datenschutzbeauftragten. Du hast au\xDFerdem das Recht auf Beschwerde beim Bayerischen Landesbeauftragten f\xFCr den Datenschutz, Wagm\xFCllerstra\xDFe 18, 80538 M\xFCnchen, <a href="https://www.datenschutz-bayern.de"target="_blank"rel="noopener">www.datenschutz-bayern.de</a>.</p>

 ${e?`<div class="card"style="padding:12px">
 <strong>Meine Daten</strong>
 <p style="margin:6px 0 10px">Lade alle deine gespeicherten Daten herunter oder l\xF6sche sie samt Konto.</p>
 <div class="form-actions"style="justify-content:flex-start;gap:8px;flex-wrap:wrap">
 <button class="secondary"type="button"onclick="dsExport()">\u2B07 Meine Daten herunterladen</button>
 <button class="secondary"type="button"onclick="dsMeineDatenLoeschen()">\u{1F5D1} Meine Daten &amp; Konto l\xF6schen</button>
 ${isAdmin()?'<button class="secondary"type="button"onclick="dsKlasseLoeschen()">\u{1F5D1} Schuljahresende: Klasse l\xF6schen (Admin)</button>':""}
 </div></div>`:""}

 <div class="form-actions"><button class="secondary"onclick="closeModal()">Schlie\xDFen</button></div>
 </div>`)}
window.showDatenschutz=showDatenschutz;window.dsExport=dsExport;window.dsMeineDatenLoeschen=dsMeineDatenLoeschen;window.dsKlasseLoeschen=dsKlasseLoeschen;


function tile(icon,title,text,target){return`<a class="card tile"href="#${target}"><span class="emoji">${icon}</span>
<strong>${title}</strong><small>${text}</small></a>`}
function statusDot(s){return`<span class="dot ${s}"></span>`}
function isApproved(){return profile?.status==="approved"}
function isTeacher(){return isApproved() && (profile?.role==="teacher"||profile?.role==="admin")}
function isAdmin(){return isApproved() && profile?.role==="admin"}
function updateTeacherTeamNav(){
 const sidebar=$("sidebar");
 if(!sidebar)return;
 lxNavRollen();

 // Lernressourcen bleiben als eigene Seite/Kachel verfügbar,
 // werden aber NICHT in der linken Seiten-Navigation angezeigt.
 sidebar.querySelectorAll('a[href="#ressourcen"],button[data-page="ressourcen"],.nav-link[data-page="ressourcen"]')
 .forEach(el=>el.remove());

 // Remove the obsolete visible wording everywhere inside the sidebar.
 const walker=document.createTreeWalker(sidebar,NodeFilter.SHOW_TEXT);
 const nodes=[];let n;
 while((n=walker.nextNode()))nodes.push(n);
 nodes.forEach(node=>{
 node.textContent=node.textContent.replace(/Team\s*&\s*SQ/gi,"");
 });

 // Find the actual team navigation item and give it exactly the requested label.
 const links=[...sidebar.querySelectorAll('a[href="#team"],button[data-page="team"],.nav-link[data-page="team"]')];
 const link=links[0];
 if(link){
 link.textContent="Lehrkräfte Klassenteam";
 link.hidden=!isTeacher();
 link.setAttribute("aria-hidden",String(!isTeacher()));
 }
}
function showAuth(){
 $("authScreen").hidden=false;$("app").hidden=true;$("logoutBtn").hidden=true;
 if($("motivBtn"))$("motivBtn").hidden=true;
 $("userName").textContent="";
}
function showApp(){
 $("authScreen").hidden=true;$("app").hidden=false;$("logoutBtn").hidden=false;
 $("userName").textContent=anzeigeName(profile,currentUser);
 if($("recoveryBtn"))$("recoveryBtn").hidden=!(profile?.pseudonym&&isTeacher()&&String(currentUser?.email||"").endsWith("@"+PSEUDO_DOMAIN));

 motivButtonAktualisieren();
 updateTeacherTeamNav();
 render();
}
function clearListeners(){unsubscribers.forEach(u=>u&&u());unsubscribers=[]}

async function ensureProfile(user, displayName="", extra={}){
 const ref=doc(db,"users",user.uid), snap=await getDoc(ref);
 if(!snap.exists()){
 const ps=(extra.pseudonym||"").trim();
 await setDoc(ref,{
 uid:user.uid,pseudonym:ps,displayName:ps,
 role:"student",status:"pending",createdAt:serverTimestamp()
 });
 }
 const s=await getDoc(ref);profile=s.data();
 /* Altkonten: Klarnamen und E-Mail aus dem Profil entfernen, sobald ein Pseudonym gesetzt ist */
 if(profile&&profile.pseudonym&&(profile.firstName||profile.lastName||profile.email||profile.displayName!==profile.pseudonym||profile.zugangscode)){
  try{await updateDoc(ref,{firstName:"",lastName:"",email:"",zugangscode:"",displayName:profile.pseudonym});const s2=await getDoc(ref);profile=s2.data()}catch(e){console.warn("Profil bereinigen:",e)}
 }
 notenLiveZuruecksetzen();try{deleteDoc(doc(db,"noten",user.uid)).catch(()=>{})}catch(e){}
 syncProfilPublic();if(isTeacher())syncProfilePublicAlle();
}

/* Öffentliches Kurzprofil (Name, Rolle, Geburtstag) – damit die vollständigen Konten (E-Mail usw.) nur für die Person selbst und Lehrkräfte lesbar sind. */
function profilPublicDaten(u,uid){return{uid:uid,displayName:u.pseudonym||"",firstName:"",lastName:"",role:u.role||"student",status:u.status||"pending",birthday:"",updatedAt:serverTimestamp()}}
async function syncProfilPublic(){
 try{if(!profile||!currentUser)return;await setDoc(doc(db,"profilePublic",currentUser.uid),profilPublicDaten(profile,currentUser.uid))}catch(e){console.warn("Kurzprofil:",e)}
}
async function syncProfilePublicAlle(){
 try{
  if(!isTeacher())return;
  const heute=new Date().toISOString().slice(0,10);
  try{if(localStorage.getItem("profilPublicSync")===heute)return}catch(e){}
  const s=await getDocs(collection(db,"users"));
  for(const d of s.docs){try{await setDoc(doc(db,"profilePublic",d.id),profilPublicDaten(d.data(),d.id))}catch(e){}}
  try{localStorage.setItem("profilPublicSync",heute)}catch(e){}
 }catch(e){console.warn("Kurzprofile:",e)}
}


function showLoginForm(){
 $("loginTab").classList.add("active");
 $("registerTab").classList.remove("active");
 $("loginForm").hidden=false;
 $("registerForm").hidden=true;$("resetForm").hidden=true;
 $("authError").textContent="";
}
function showRegisterForm(){
 $("registerTab").classList.add("active");
 $("loginTab").classList.remove("active");
 $("loginForm").hidden=true;
 $("registerForm").hidden=false;$("resetForm").hidden=true;
 $("authError").textContent="";
}

/* =========================================================
 LERNRESSOURCEN – ANLEGEN
 Nur freigeschaltete Lehrkräfte/Admins dürfen Ressourcen
 erstellen. Die bestehende Anzeige bleibt unverändert.
 ========================================================= */
window.openLernressourceForm=async function(vorgabeTyp){
 if(!isTeacher()){
 toast("Nur freigeschaltete Lehrkräfte können Lernressourcen anlegen.");
 return;
 }

 try{ await loadFirebase(); }catch(e){
 console.error("Firebase für Lernressource:",e);
 toast("Firebase ist noch nicht bereit. Bitte erneut versuchen.");
 return;
 }

 modal(`<button class="modal-close"type="button"onclick="closeModal()">×</button>
 <div class="kicker">LERNRESSOURCE</div>
 <h2>Neue Lernressource</h2>
 <p>Lege eine Ressource für den gemeinsamen Campus an.</p>
 <div class="form">
 <label>Titel<input id="lrTitle"type="text"maxlength="200"placeholder="Titel der Lernressource"></label>
 <label>Art
 <select id="lrType">
 <option value="taskcard">TaskCard</option>
 <option value="ki">KI-Lernressource</option>
 <option value="video">Video</option>
 <option value="bycs">ByCS / mebis</option>
 <option value="canva">Canva</option>
 <option value="learningapps">LearningApps</option>
 <option value="website">Webseite</option>
 <option value="external">Externer Link</option>
 </select>
 </label>
 <label>Link / URL<input id="lrUrl"type="url"maxlength="2000"placeholder="https://..."></label>
 <label>Beschreibung<textarea id="lrDescription"rows="4"maxlength="2000"placeholder="Kurzbeschreibung"></textarea></label>
 <label>Fach / Lernbereich<input id="lrSubject"type="text"maxlength="150"placeholder="z. B. Betriebswirtschaft"></label>
 <label>Schlagworte<input id="lrTags"type="text"maxlength="500"placeholder="z. B. Prüfung, Grundlagen, Übung"></label>
 <div class="form-actions">
 <button class="secondary"type="button"onclick="closeModal()">Abbrechen</button>
 <button class="primary"type="button"id="lrSave">Lernressource anlegen</button>
 </div>
 </div>`);
 if(typeof vorgabeTyp==="string"){const sel=document.getElementById("lrType");if(sel&&[...sel.options].some(o=>o.value===vorgabeTyp))sel.value=vorgabeTyp;}

 const save=document.getElementById("lrSave");
 if(!save)return;
 save.addEventListener("click",async()=>{
 const title=document.getElementById("lrTitle")?.value.trim()||"";
 const type=document.getElementById("lrType")?.value||"external";
 const url=document.getElementById("lrUrl")?.value.trim()||"";
 const description=document.getElementById("lrDescription")?.value.trim()||"";
 const subject=document.getElementById("lrSubject")?.value.trim()||"";
 const tags=(document.getElementById("lrTags")?.value||"").split(",").map(x=>x.trim()).filter(Boolean);

 if(!title){toast("Bitte einen Titel eingeben.");return;}
 if(!url){toast("Bitte einen Link / eine URL eingeben.");return;}
 try{
 const u=new URL(url);
 if(!/^https?:$/.test(u.protocol))throw new Error("protocol");
 }catch(e){toast("Bitte eine gültige http(s)-URL eingeben.");return;}

 if(!currentUser || !db){toast("Firebase ist noch nicht bereit. Bitte erneut versuchen.");return;}
 if(!isTeacher()){toast("Dein Lehrkraft-Zugang ist nicht freigeschaltet.");return;}

 save.disabled=true;
 save.textContent="Wird gespeichert …";
 try{
 await addDoc(collection(db,"lernressourcen"),{
 title,type,url,description,subject,tags,
 createdBy:currentUser.uid,
 createdByName:anzeigeName(profile,currentUser),
 createdAt:serverTimestamp(),
 updatedAt:serverTimestamp()
 });
 closeModal();
 toast("Lernressource wurde angelegt.");
 await render();
 }catch(e){
 console.error("Lernressource anlegen:",e);
 save.disabled=false;
 save.textContent="Lernressource anlegen";
 if(e?.code==="permission-denied"){
 toast("Firebase verweigert das Anlegen. Bitte die veröffentlichten Firestore-Regeln prüfen.");
 }else{
 toast("Die Lernressource konnte nicht angelegt werden.");
 }
 }
 });
};

function openLernressource(encodedUrl){
 try{
 const url=decodeURIComponent(encodedUrl);
 window.open(url,"_blank","noopener,noreferrer");
 }catch(e){
 console.error("Lernressource öffnen:",e);
 toast("Die Ressource konnte nicht geöffnet werden.");
 }
}

function editLernressourceForm(collectionName,id,title,type,url,description,subject,tagsText){
 if(!isTeacher()){toast("Nur freigeschaltete Lehrkräfte können Lernressourcen bearbeiten.");return}
 window.__editLernressourceCollection=collectionName||"lernressourcen";
 window.__editLernressourceId=id;
 modal(`<button class="modal-close"type="button"onclick="closeModal()">×</button>
 <div class="kicker">LERNRESSOURCE</div>
 <h2>Lernressource bearbeiten</h2>
 <div class="form">
 <label>Titel<input id="lrTitle"type="text"maxlength="200"value="${esc(title||"")}"></label>
 <label>Art
 <select id="lrType">
 <option value="taskcard">TaskCard</option>
 <option value="ki">KI-Lernressource</option>
 <option value="video">Video</option>
 <option value="bycs">ByCS / mebis</option>
 <option value="canva">Canva</option>
 <option value="learningapps">LearningApps</option>
 <option value="website">Webseite</option>
 <option value="external">Externer Link</option>
 </select>
 </label>
 <label>Link / URL<input id="lrUrl"type="url"maxlength="2000"value="${esc(url||"")}"></label>
 <label>Beschreibung<textarea id="lrDescription"rows="4"maxlength="2000">${esc(description||"")}</textarea></label>
 <label>Fach / Lernbereich<input id="lrSubject"type="text"maxlength="150"value="${esc(subject||"")}"></label>
 <label>Schlagworte<input id="lrTags"type="text"maxlength="500"value="${esc(tagsText||"")}"></label>
 <div class="form-actions">
 <button class="secondary"type="button"onclick="closeModal()">Abbrechen</button>
 <button class="primary"type="button"id="lrUpdateSave">Änderungen speichern</button>
 </div>
 </div>`);
 const typeSel=$("lrType");
 if(typeSel)typeSel.value=type||"external";
 const btn=$("lrUpdateSave");
 if(btn)btn.addEventListener("click",updateLernressource);
}

async function updateLernressource(){
 const collectionName=window.__editLernressourceCollection||"lernressourcen";
 const id=window.__editLernressourceId;
 if(!id)return;
 const title=$("lrTitle")?.value.trim()||"";
 const type=$("lrType")?.value||"external";
 const url=$("lrUrl")?.value.trim()||"";
 const description=$("lrDescription")?.value.trim()||"";
 const subject=$("lrSubject")?.value.trim()||"";
 const tags=($("lrTags")?.value||"").split(",").map(x=>x.trim()).filter(Boolean);

 if(!title){toast("Bitte einen Titel eingeben.");return}
 if(!url){toast("Bitte einen Link / eine URL eingeben.");return}
 try{
 const u=new URL(url);
 if(!/^https?:$/.test(u.protocol))throw new Error("protocol");
 }catch(e){toast("Bitte eine gültige http(s)-URL eingeben.");return}

 const btn=$("lrUpdateSave");
 if(btn){btn.disabled=true;btn.textContent="Speichert …"}
 try{
 await updateDoc(doc(db,collectionName,id),{title,type,url,description,subject,tags,updatedAt:serverTimestamp()});
 closeModal();toast("Lernressource wurde geändert.");await render();
 }catch(e){
 console.error("Lernressource bearbeiten:",e);
 if(btn){btn.disabled=false;btn.textContent="Änderungen speichern"}
 toast(e?.code==="permission-denied"?"Firebase verweigert die Änderung. Bitte die Firestore-Regeln prüfen.":"Änderungen konnten nicht gespeichert werden.");
 }
}

