const CHECKIN_NEU={
t12_1_1:{tz:"Entwicklungsbedingungen zuordnen",tf:"Zusammenwirken erklären",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Anlage=Genetisch mitgegebene Voraussetzungen", "Umwelt=Äußere Einflüsse wie Familie, Freunde und Kultur", "Selbststeuerung=Der Mensch gestaltet seine Entwicklung aktiv mit"]],
 f:["F", "Erkläre an einem Beispiel, wie Anlage, Umwelt und Selbststeuerung bei der Entwicklung zusammenwirken.", "Beispiel Sprache: Die Anlage ermöglicht dem Kind das Sprechenlernen, die Umwelt liefert Sprache und Ansprache, und durch eigenes Nachfragen und Üben steuert das Kind seine Entwicklung selbst mit. Keiner der Faktoren wirkt allein."]},
t12_1_2:{tz:"Instanzen zuordnen",tf:"Zusammenspiel der Instanzen",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Es=Folgt dem Lustprinzip und will Triebwünsche sofort erfüllen", "Ich=Folgt dem Realitätsprinzip und vermittelt", "Über-Ich=Vertritt Moral, Gewissen und Normen"]],
 f:["F", "Beschreibe an einer Alltagssituation, wie Es, Ich und Über-Ich zusammenspielen.", "Beispiel: Nina hat Lust, in der Prüfung abzuschreiben (Es). Das Über-Ich meldet sich mit schlechtem Gewissen. Das Ich wägt die Folgen ab und entscheidet sich, selbst zu schreiben."]},
t12_1_3:{tz:"Phasen in Reihenfolge",tf:"Fixierung erklären",
 z:["R", "Bringe die Phasen der psychosexuellen Entwicklung nach Freud in die richtige Reihenfolge.", ["Orale Phase", "Anale Phase", "Phallische Phase", "Latenzphase", "Genitale Phase"]],
 f:["F", "Erkläre mit eigenen Worten, was Fixierung bedeutet, und nenne ein Beispiel.", "Fixierung heißt, dass ein Mensch in einer Phase „hängen bleibt“, wenn dort Bedürfnisse zu stark oder zu wenig befriedigt wurden. Beispiel: Wer in der oralen Phase zu kurz kam, kaut als Erwachsener vielleicht Nägel oder raucht."]},
t12_1_4:{tz:"Abwehrmechanismen zuordnen",tf:"Abwehr am Beispiel erklären",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Verdrängung=Unangenehme Inhalte werden ins Unbewusste geschoben", "Projektion=Eigene Gefühle oder Eigenschaften werden anderen zugeschrieben", "Regression=Rückfall auf eine frühere Entwicklungsstufe", "Identifikation=Eigenschaften eines Vorbildes werden übernommen"]],
 f:["F", "Wozu dienen Abwehrmechanismen? Erkläre es an einem Beispiel.", "Sie schützen das Ich vor unangenehmen Gefühlen wie Angst oder Schuld. Beispiel: Ein Schüler, der selbst oft unkonzentriert ist, wirft den anderen vor, sie würden ständig stören (Projektion)."]},
t12_1_5:{tz:"Würdigung ergänzen",tf:"Stärke und Schwäche nennen",
 z:["L", "Freuds Theorie ist empirisch schwer ___. Als Stärke gilt, dass sie die Bedeutung der frühen ___ betont.", ["überprüfbar", "Kindheitserfahrungen"], ["überprüft", "Methoden"]],
 f:["F", "Nenne eine Stärke und eine Schwäche von Freuds Theorie.", "Stärke: Sie betont die Bedeutung früher Kindheitserfahrungen und des Unbewussten. Schwäche: Viele Annahmen sind empirisch schwer überprüfbar, und die Betonung der Sexualität gilt als einseitig."]},
t12_1_6:{tz:"Bindungstypen zuordnen",tf:"Fremde Situation beschreiben",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Sicher gebunden=Protestiert bei der Trennung und lässt sich bei der Rückkehr schnell beruhigen", "Unsicher-vermeidend=Ignoriert die Bezugsperson bei der Rückkehr", "Unsicher-ambivalent=Sucht Nähe, wehrt sie aber zugleich ab"]],
 f:["F", "Beschreibe, wie sich ein sicher gebundenes Kind in der Fremden Situation verhält.", "Es erkundet den Raum, solange die Bezugsperson da ist (sichere Basis), protestiert bei der Trennung, begrüßt die Bezugsperson bei der Rückkehr und lässt sich schnell beruhigen."]},
t12_1_6t:{tz:"Bindungstypen zuordnen",tf:"Fremde Situation beschreiben",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Sicher gebunden=Protestiert bei der Trennung und lässt sich bei der Rückkehr schnell beruhigen", "Unsicher-vermeidend=Ignoriert die Bezugsperson bei der Rückkehr", "Unsicher-ambivalent=Sucht Nähe, wehrt sie aber zugleich ab"]],
 f:["F", "Beschreibe, wie sich ein sicher gebundenes Kind in der Fremden Situation verhält.", "Es erkundet den Raum, solange die Bezugsperson da ist (sichere Basis), protestiert bei der Trennung, begrüßt die Bezugsperson bei der Rückkehr und lässt sich schnell beruhigen."]},
t12_1_6b:{tz:"Bestandteile zuordnen",tf:"Feinfühligkeit und Verwöhnen",
 z:["Z", "Ordne jedem Bestandteil der Feinfühligkeit die passende Beschreibung zu.", ["Wahrnehmen=Auch feine Signale des Kindes werden bemerkt", "Richtig interpretieren=Das Verhalten wird nicht durch eigene Wünsche und Stimmungen verzerrt", "Angemessen reagieren=Die Reaktion passt zum Bedürfnis des Kindes", "Prompt reagieren=Das Kind erlebt die Reaktion als Folge seines Signals"]],
 f:["F", "Erkläre, warum prompte Reaktion auf die Signale eines Säuglings kein Verwöhnen ist.", "Säuglinge können ihre Gefühle noch nicht selbst regulieren und sind auf die Ko-Regulation durch die Bindungsperson angewiesen. Reagiert sie feinfühlig und prompt, erlebt das Kind, dass seine Bedürfnisse zählen. So entstehen Urvertrauen und Selbstwert, und das Kind lernt allmählich die Selbstregulation."]},
t12_1_7:{tz:"Bindungsbeziehungen zuordnen",tf:"Veränderung der Bindung",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Primäre Bindung=Enge Beziehung zu den Eltern oder einer Hauptbezugsperson", "Jugendalter=Gleichaltrige und Freunde gewinnen an Bedeutung", "Erwachsenenalter=Die Partnerschaft wird oft zur wichtigsten Bindung"]],
 f:["F", "Wie verändern sich Bindungsbeziehungen vom Kindes- bis zum Erwachsenenalter?", "Zuerst stehen die Eltern als primäre Bindungspersonen im Mittelpunkt. Im Jugendalter gewinnen Gleichaltrige und Freunde an Bedeutung, die Bindung an die Eltern bleibt, wird aber gleichberechtigter. Im Erwachsenenalter wird die Partnerschaft oft zur wichtigsten Bindung."]},
t12_1_8:{tz:"Eingewöhnung ordnen",tf:"Feinfühligkeit begründen",
 z:["R", "Bringe die Schritte einer behutsamen Eingewöhnung in der Kita in eine sinnvolle Reihenfolge.", ["Das Kind lernt gemeinsam mit einem Elternteil die Einrichtung kennen", "Die Bezugserzieherin baut vorsichtig Kontakt auf", "Erster kurzer Trennungsversuch", "Die Trennungszeiten werden schrittweise verlängert", "Das Kind nutzt die Erzieherin als sichere Basis"]],
 f:["F", "Warum ist Feinfühligkeit der Erzieherin für die Bindungsförderung wichtig?", "Feinfühlige Erzieherinnen nehmen Signale des Kindes wahr, deuten sie richtig und reagieren prompt und angemessen. So erlebt das Kind Sicherheit und kann die Erzieherin als sichere Basis nutzen."]},
t12_1_9:{tz:"Lebensspanne zuordnen",tf:"Gewinne und Verluste",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Lebensspannenperspektive=Entwicklung dauert ein Leben lang", "Jugendalter=Typische Anforderung: die eigene Identität finden", "Frühes Erwachsenenalter=Typische Anforderung: Beruf und Partnerschaft gestalten"]],
 f:["F", "Erkläre Baltes’ Gedanken, dass Entwicklung aus Gewinnen und Verlusten besteht, an einem Beispiel.", "In jedem Lebensabschnitt können Fähigkeiten dazukommen (Gewinn) und andere wegfallen (Verlust). Beispiel: Ein Jugendlicher gewinnt Selbstständigkeit, verliert aber die Geborgenheit der Kindheit."]},
t12_1_10:{tz:"Begriffe der Resilienz zuordnen",tf:"Risiko und Schutz",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Vulnerabilität=Erhöhte Verletzbarkeit", "Resilienz=Psychische Widerstandsfähigkeit gegenüber Belastungen", "Risikofaktor=Erhöht die Wahrscheinlichkeit für Entwicklungsprobleme", "Schutzfaktor=Stärkt die Widerstandskraft, zum Beispiel soziale Unterstützung"]],
 f:["F", "Nenne je zwei Risiko- und zwei Schutzfaktoren und erkläre, wie sie zusammenwirken.", "Risikofaktoren: chronische Konflikte in der Familie, Armut. Schutzfaktoren: soziale Unterstützung, ein positives Selbstbild. Schutzfaktoren können Risiken abpuffern, sodass ein Kind trotz Belastung stabil bleibt (Resilienz)."]},
t12_2_01:{tz:"Begriff zuordnen",tf:"Begriff am Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["zeitstabil=bleibt über längere Zeit ähnlich", "situationsübergreifend=zeigt sich in verschiedenen Situationen", "veränderbar=kann sich durch Erfahrungen wandeln", "einzigartig=unverwechselbare Kombination der Merkmale"]],
 f:["F", "Erkläre die Merkmale des Persönlichkeitsbegriffs an einem Beispiel aus deinem Alltag.", "Persönlichkeit besteht aus Merkmalen wie Hilfsbereitschaft. Sie sind zeitstabil (zeigt sich seit Jahren), situationsübergreifend (zu Hause und in der Schule), veränderbar (durch Erfahrungen) und einzigartig (andere haben eine andere Kombination)."]},
t12_2_02:{tz:"Testbegriffe zuordnen",tf:"Test beurteilen",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Persönlichkeitsinventar=Fragebogen zur Messung ausgewählter Merkmale", "B5T=Test mit 50 Aufgaben", "FPI=Test mit 138 Ja/Nein-Aussagen", "offene Frage=freie Antwort"]],
 f:["F", "Erkläre, wie ein Persönlichkeitsinventar funktioniert und welche Grenze es hat.", "Ein Inventar ist ein Fragebogen, in dem sich die Person selbst beschreibt. So werden ausgewählte Merkmale und ihre Ausprägung messbar. Grenze: Es erfasst nur einzelne Merkmale und die Selbsteinschätzung kann verzerrt sein."]},
t12_2_03:{tz:"Faktoren zuordnen",tf:"Person beschreiben",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Openness=Offenheit", "Conscientiousness=Gewissenhaftigkeit", "Extraversion=nach außen gewandt", "Agreeableness=Verträglichkeit", "Neuroticism=emotionale Stabilität/Labilität"]],
 f:["F", "Beschreibe eine Person, die du gut kennst, mit drei der Big-Five-Faktoren.", "Meine Freundin ist extravertiert (sucht Kontakt, gesprächig), gewissenhaft (ordentlich, zuverlässig) und verträglich (hilfsbereit, gibt nach). So beschreibe ich ihre Ausprägung, erkläre aber nicht, warum sie so ist."]},
t12_2_04:{tz:"Schritte zuordnen",tf:"Profil im Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["nennen=Faktor und Ausprägung festhalten", "erklären=Bedeutung der Ausprägung", "verdeutlichen=Beleg aus dem Fall", "Profil=Ausprägungen der fünf Faktoren"]],
 f:["F", "Beschreibe in drei Schritten (nennen, erklären, verdeutlichen) einen Faktor einer Person aus einem Fall.", "Extraversion: hoch. Das heißt hohe Geselligkeit und Gesprächigkeit. Im Fall spricht die Person in der Pause alle neuen Mitschüler an."]},
t12_2_05:{tz:"Begriffe zu Rogers zuordnen",tf:"Rogers’ Haltung erklären",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["humanistische Psychologie=dritte Kraft", "klientenzentrierte Therapie=Gesprächstherapie nach Rogers", "Menschenbild=positiv und konstruktiv", "subjektive Erfahrung=Erleben aus Sicht der Person"]],
 f:["F", "Erkläre, was an Rogers’ Theorie „personenzentriert“ ist.", "Die Person mit ihrem Erleben steht im Mittelpunkt. Rogers will ihre subjektive Erfahrung verstehen und vertraut auf ihre Möglichkeiten, statt sie zu formen."]},
t12_2_06:{tz:"Klima zuordnen",tf:"Menschenbilder vergleichen",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Angstfreiheit=keine Bedrohung", "einfühlendes Verständnis=sich in das Erleben hineinversetzen", "Wertschätzung=Akzeptieren unabhängig von Leistung", "Aufrichtigkeit=echt und ehrlich sein"]],
 f:["F", "Vergleiche kurz das Menschenbild von Rogers mit dem von Freud.", "Rogers: Der Mensch ist grundsätzlich positiv und konstruktiv und strebt nach Selbstverwirklichung. Freud: Der Mensch ist triebbestimmt und im Konflikt zwischen Trieben und Abwehr."]},
t12_2_07:{tz:"Richtungen zuordnen",tf:"Bewertung erklären",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Erhaltung=Grundbedürfnisse befriedigen", "Entfaltung=Wachstum und Differenzierung", "Autonomie=Unabhängigkeit und Selbstbestimmung", "organismischer Bewertungsprozess=Erfahrungen als förderlich oder hinderlich bewerten"]],
 f:["F", "Erkläre an einem Beispiel den organismischen Bewertungsprozess.", "Ein Kind lernt gehen: Die Eltern helfen, bis es allein geht. Der Organismus bewertet die Erfahrung positiv, weil sie die Selbstverwirklichung fördert. Wird es nur festgehalten, bewertet es negativ und reagiert mit Trotz."]},
t12_2_08:{tz:"Selbstkonzept zuordnen",tf:"Diskrepanz am Beispiel",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Selbstkonzept=Gesamtheit der Wahrnehmungen und Bewertungen über sich", "Real-Selbst=tatsächliches Bild von sich", "Ideal-Selbst=Bild, wie man sein möchte", "Diskrepanz=Abstand zwischen Real- und Ideal-Selbst"]],
 f:["F", "Erkläre das Selbstkonzept mit Real- und Ideal-Selbst an einem Beispiel.", "Das Selbstkonzept ist die Gesamtheit aller Wahrnehmungen und Bewertungen über sich selbst. Real-Selbst: „Ich bin still.“ Ideal-Selbst: „Ich möchte mutig sein.“ Ein großer Abstand erzeugt Spannung."]},
t12_2_09:{tz:"Einflüsse zuordnen",tf:"Wirkung erklären",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Erfahrung=selbst erlebte Erfolge und Misserfolge", "Forderung=Gebote und Verbote der Bezugspersonen", "Beziehungsbotschaft=Rückmeldung zur Person", "Selbst-Konsistenz=Übereinstimmung mit dem Selbstbild"]],
 f:["F", "Erkläre, wie sich ein negatives Selbstkonzept selbst bestätigen kann.", "Wer sich für kontaktscheu hält, vermeidet Kontakte. Dadurch fehlen Erfahrung und Übung, es entsteht Misserfolg und Kontakthemmung. Das bestätigt das Selbstbild."]},
t12_2_10:{tz:"Begriffe zuordnen",tf:"Selbstregulation am Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Selbstregulation=Ziele setzen, Strategien entwerfen, Verhalten bewerten", "Selbstwirksamkeit=Überzeugung, Situationen zu bewältigen", "Selbstevaluation=Bewertung des eigenen Verhaltens", "Ergebniserwartung=Wahrscheinlichkeit von Erfolg oder Misserfolg"]],
 f:["F", "Erkläre Selbstwirksamkeit und Selbstevaluation an einem Beispiel.", "Selbstwirksamkeit: Vor der Prüfung denkt Anja „Ich schaffe das“. Selbstevaluation: Nach der Prüfung bewertet sie, was gut lief und was nicht."]},
t12_2_11:{tz:"Identitätstypen zuordnen",tf:"Identitätstyp im Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["erarbeitet=Verpflichtung hoch, Experimentieren hoch", "übernommen=Verpflichtung hoch, Experimentieren niedrig", "diffus=Verpflichtung niedrig, Experimentieren niedrig", "Identität=Selbstverständnis als einmalige Person"]],
 f:["F", "Erkläre das Identitätsmodell nach Marcia an einem Beispiel.", "Marcia unterscheidet nach Verpflichtung und Experimentierfreudigkeit. Beispiel: Andreas hat verschiedene Möglichkeiten geprüft und sich bewusst entschieden (erarbeitete Identität)."]},
t12_2_12:{tz:"Begriffe zuordnen",tf:"Abwehr erklären",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["flexibles Selbstkonzept=Erfahrungen werden integriert", "starres Selbstkonzept=Erfahrungen werden abgewehrt", "Wahrnehmungsverleugnung=Erfahrung wird negiert", "Wahrnehmungsverzerrung=Bedeutung wird entstellt"]],
 f:["F", "Erkläre den Zusammenhang zwischen Selbstachtung und Flexibilität des Selbstkonzepts.", "Wer bedingungslose positive Beachtung erfährt, hat hohe Selbstachtung. Dann können Erfahrungen in das Selbstkonzept integriert werden. Bei geringer Selbstachtung wird das Selbstkonzept starr und Erfahrungen werden abgewehrt."]},
t12_2_13:{tz:"Ebenen zuordnen",tf:"Zwei Ebenen im Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Organismus=spontan, flexibel, Bezugspunkt innen", "Selbstkonzept=verinnerlichte Werte, Bezugspunkt außen", "Internalisierung=Übernahme fremder Werturteile", "Selbstaktualisierung=Erfahrungen, die für Selbstachtung bedeutsam sind"]],
 f:["F", "Erkläre die zwei Ebenen des Bewertens an einem Beispiel.", "Ein Kind zieht seine Schwester an den Haaren (Erleben des Organismus), hört „böser Bub“ und übernimmt das Urteil (Selbstkonzept). Beide Ebenen können in Spannung stehen."]},
t12_2_14:{tz:"Begriffe zuordnen",tf:"Kongruenz am Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Kongruenz=Selbstkonzept und Erleben stimmen überein", "Inkongruenz=Selbstkonzept und Erleben widersprechen sich", "wahres Selbst=das, was die Person im Kern erlebt", "Selbstentfremdung=wahres Selbst wird verdrängt"]],
 f:["F", "Erkläre Inkongruenz an einem Beispiel aus dem Alltag.", "Ein Kind sieht sich als „immer lieb“ und spürt Wut. Selbstkonzept und Erleben passen nicht zusammen, das ist Inkongruenz."]},
t12_2_15:{tz:"Wege zuordnen",tf:"Bewältigung erklären",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Weg A=Erweiterung des Selbstkonzepts", "Weg B=Verteidigung des Selbstkonzepts", "Wahrnehmungsverleugnung=Erfahrung wird nicht wahrgenommen", "Wahrnehmungsverzerrung=Erfahrung wird umgedeutet"]],
 f:["F", "Erkläre, wie sich Weg A und Weg B unterscheiden.", "Weg A: Hohe Selbstachtung, flexibles Selbstkonzept, es wird erweitert. Weg B: Geringe Selbstachtung, starres Selbstkonzept, es wird durch Abwehr verteidigt und der Konflikt bleibt."]},
t12_2_16:{tz:"Bausteine zuordnen",tf:"Entstehung erklären",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["bestehende Inkongruenz=Selbstkonzept und Erleben passen nicht zusammen", "starres Selbstkonzept=Erfahrungen werden nicht integriert", "Lebensereignis=Auslöser, der den Konflikt verschärft", "Symptom=Ausdruck des inneren Konflikts"]],
 f:["F", "Erkläre kurz, wie nach Rogers eine psychische Störung entsteht.", "Inkongruenz, ein starres Selbstkonzept und ein aktuelles Lebensereignis führen zu einem inneren Konflikt, der sich in einem Symptom äußert."]},
t12_2_17:{tz:"Haltungen zuordnen",tf:"Haltung im Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Wertschätzung=Achtung, Anerkennung und Wärme", "Verstehen=Einfühlen in die innere Welt", "Echtheit=Aufrichtigkeit der Fachkraft", "Bewertungsbedingung=Maßstab, der für Zuneigung erfüllt werden muss"]],
 f:["F", "Erkläre, warum bedingungslose positive Beachtung für die Erziehung wichtig ist.", "Sie stärkt die Selbstachtung und ein flexibles Selbstkonzept. Kinder können Gefühle annehmen und entwickeln Kongruenz. Fehlt sie, entstehen Bewertungsbedingungen und Inkongruenz."]},
t12_2_18:{tz:"Würdigung zuordnen",tf:"Würdigung schreiben",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Stärke=positives Menschenbild", "Schwäche=begrenzter Erklärungswert", "Fazit=abwägendes Gesamturteil", "kritische Würdigung=Stärken und Schwächen abwägen"]],
 f:["F", "Nenne eine Stärke und eine Schwäche der personenzentrierten Theorie mit Begründung.", "Stärke: Das positive Menschenbild ist eine Alternative zu Marionette und Triebwesen. Schwäche: Der Erklärungswert ist begrenzt, denn Wahrnehmung und Denken werden kaum erfasst."]},
t12_2_19:{tz:"Theorien zuordnen",tf:"Theorien vergleichen",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Freud=Mensch triebbestimmt", "Rogers=Mensch positiv und konstruktiv", "Aktualisierungstendenz=Antrieb bei Rogers", "Triebe=Antrieb bei Freud"]],
 f:["F", "Vergleiche Freud und Rogers in zwei Punkten.", "Menschenbild: Freud sieht den Menschen als triebbestimmt, Rogers als positiv und konstruktiv. Antrieb: Freud nennt Triebe, Rogers die Aktualisierungstendenz."]},
t12_3_01:{tz:"Begriff zuordnen",tf:"Begriff am Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Soziale Arbeit=berufsmäßige, wissenschaftlich fundierte Hilfe", "Sozialpädagogik=Teilbereich mit erzieherischer Absicht", "öffentlicher Träger=Einrichtung in staatlicher Verantwortung", "freier Träger=private, meist gemeinnützige Organisation"]],
 f:["F", "Erkläre den Begriff Soziale Arbeit und nenne ein Beispiel.", "Soziale Arbeit ist berufsmäßige, wissenschaftlich fundierte Hilfe für Menschen aller Altersgruppen bei Problem- und Notsituationen, z. B. die Beratung einer Familie im Jugendamt."]},
t12_3_02:{tz:"Bereich zuordnen",tf:"Bereich am Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Kinder- und Jugendhilfe=Entwicklung fördern, Benachteiligung abbauen", "Sozialhilfe=Lebensunterhalt für Menschen in Not", "Gesundheitshilfe=Förderung und Wiederherstellung der Gesundheit", "Altenhilfe=Teilhabe im Alter ermöglichen"]],
 f:["F", "Nenne die vier Aufgabenbereiche und je ein Praxisbeispiel.", "Kinder- und Jugendhilfe: Jugendarbeit; Sozialhilfe: Wohnungslosenhilfe; Gesundheitshilfe: Sozialdienst im Krankenhaus; Altenhilfe: Seniorentreff."]},
t12_3_03:{tz:"Schritt zuordnen",tf:"Schritt am Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Analyse=Problem genau erfassen, Beziehung aufbauen", "Planung=Ziele und Vorgehensplan entwickeln", "Handlung=Intervention nach dem Plan", "Bewertung=prüfen, ob die Ziele erreicht wurden"]],
 f:["F", "Erkläre, was ein Handlungskonzept ist, und nenne seine vier Schritte.", "Ein Handlungskonzept ist ein wissenschaftlich begründeter Entwurf zum beruflichen Umgang mit sozialen Problemen. Schritte: Analyse, Planung, Handlung, Bewertung."]},
t12_3_04:{tz:"Ebene zuordnen",tf:"Ebene am Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Verhaltensebene=beobachtbares Verhalten", "kognitive Ebene=Gedanken, Erwartungen, Befürchtungen", "physiologische Ebene=körperliche Symptome", "aufrechterhaltende Bedingung=Konsequenz, die das Verhalten verstärkt"]],
 f:["F", "Erkläre die Grundannahme des verhaltensorientierten Konzepts.", "Jedes Verhalten, auch unangepasstes, ist erlernt und kann verlernt werden. Ziel ist der Abbau unerwünschten und der Aufbau erwünschten Verhaltens durch gezielte Lernhilfen."]},
t12_3_05:{tz:"Technik zuordnen",tf:"Technik am Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Gegenkonditionierung=Reiz mit unvereinbarem, angenehmem Reiz koppeln", "systematische Desensibilisierung=schrittweise Annäherung bei Entspannung", "Reizüberflutung=sofortige Konfrontation mit starken Reizen", "Aversionstherapie=anziehenden Reiz mit unangenehmem koppeln"]],
 f:["F", "Erkläre die systematische Desensibilisierung an einem Beispiel.", "Der Klient lernt Entspannung, erstellt eine Angsthierarchie (z. B. bei Spinnenangst vom Bild bis zur echten Spinne) und arbeitet die Stufen nacheinander entspannt durch. Angst und Entspannung können nicht gleichzeitig bestehen."]},
t12_3_06:{tz:"Begriff zuordnen",tf:"Begriff am Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["differentielle Verstärkung=unerwünschtes ignorieren, erwünschtes verstärken", "Verhaltensformung=kleine Schritte zum Endverhalten verstärken", "Nicht-Verstärkung=keine Beachtung des unerwünschten Verhaltens", "Gesetz der Bereitschaft=Lernen braucht Motivation und Bedürfnis"]],
 f:["F", "Erkläre die Verhaltensformung am Beispiel eines Kindes, das nicht spricht.", "Zuerst wird schon ein Laut verstärkt, später Nachahmung einzelner Laute, dann mehrerer, bis das Kind spricht. Die Verstärkung wird dann unregelmäßig und überflüssig."]},
t12_3_07:{tz:"Technik zuordnen",tf:"Technik am Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Desensibilisierung=schrittweise Annäherung bei Entspannung", "Flooding=sofortige starke Konfrontation", "Shaping=Teilschritte verstärken", "differentielle Verstärkung=Unerwünschtes ignorieren, Erwünschtes verstärken"]],
 f:["F", "Wähle für ein Kind mit Zahnarztangst eine Technik und begründe.", "Systematische Desensibilisierung oder Gegenkonditionierung: Angstreiz wird mit angenehmen, unvereinbaren Reizen gekoppelt bzw. schrittweise bei Entspannung angenähert."]},
t12_3_08:{tz:"Teil zuordnen",tf:"Teil am Beispiel",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Einleitung=Einstieg, Lernbereich, Überleitung", "Nennen=Begriff oder Schritt benennen", "Erklären=Zusammenhang darlegen", "Verdeutlichen (Transfer)=am Fall konkretisieren"]],
 f:["F", "Beschreibe, wie du im Hauptteil mit Anne vorgehst.", "Ich nenne die Schritte Analyse, Planung, Handlung, Bewertung, erkläre sie und zeige jeweils an Anne, z. B. die Analyse ihrer Schulangst auf den drei Ebenen."]},
t12_3_09:{tz:"Begriff zuordnen",tf:"Begriff am Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Ökologie=Lehre von den Beziehungen zwischen Organismus und Umwelt", "Transaktion=Wirkung und Rückwirkung zwischen Person und Umwelt", "Doppelverpflichtung=Hilfe für Person und Gestaltung der Umwelt", "Person-in-Umwelt=Verhalten im Umweltzusammenhang sehen"]],
 f:["F", "Erkläre Transaktion an einem Beispiel.", "Eine Person verändert ihre Umwelt (z. B. Häuser bauen), die veränderte Umwelt wirkt auf die Lebensverhältnisse zurück (z. B. Lärm), die Person reagiert erneut."]},
t12_3_10:{tz:"Begriff zuordnen",tf:"Begriff am Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Anpassung=Übereinstimmung von Person und Umwelt herstellen", "anpassungsfördernd=führt zu positivem Person-Umwelt-Verhältnis", "anpassungsfeindlich=führt zu Missverhältnis", "kulturelle Umwelt=Sprache, Normen, Medien"]],
 f:["F", "Erkläre den Unterschied zwischen anpassungsfördernder und anpassungsfeindlicher Transaktion an einem Beispiel.", "Ein Baggersee als Treffpunkt ist anpassungsfördernd (Übereinstimmung, Wohlbefinden), eine Autobahn durch ein Erholungsgebiet anpassungsfeindlich (Belastung, Missverhältnis)."]},
t12_3_11:{tz:"Begriff zuordnen",tf:"Begriff am Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Habitat=unmittelbarer Lebensraum", "Nische=Wirkungsfeld einer Person", "gute Nische=große Einflussmöglichkeiten", "schlechte Nische=geringe Einflussmöglichkeiten"]],
 f:["F", "Erkläre Habitat und Nische an einem Beispiel aus der Schule.", "Das Habitat ist die Schule mit Gebäude, Klasse und Kultur. Die Nische ist der Einfluss einer Schülerin, z. B. wenn sie als Klassensprecherin mitentscheidet (gute Nische) oder übergangen wird (schlechte Nische)."]},
t12_3_12:{tz:"Begriff zuordnen",tf:"Begriff am Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Lebens-Stress=Belastungszustand durch gestörte Person-Umwelt-Abstimmung", "Coping=Versuch, stressreiche Situationen zu bewältigen", "Ressourcen=Kräfte zur Bewältigung", "Selbststeuerung=Kontrolle und Verantwortung für eigenes Handeln"]],
 f:["F", "Erkläre Lebens-Stress und Coping an einem Beispiel.", "Nach einer Kündigung (Lebens-Stress, negativ, wenn als Bedrohung erlebt) sucht jemand eine Beratungsstelle auf und findet eine neue Stelle (positives Coping). Ressourcen sind Beratungsstelle und eigene Problemlösefähigkeit."]},
t12_3_13:{tz:"Begriff zuordnen",tf:"Begriff am Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Passungsgefüge=Verhältnis von Person und Umwelt", "kritisches Lebensereignis=z. B. Rollenwechsel, Verlust", "Anpassungspotenzial=Fähigkeit der Person zur Anpassung", "Umweltgestaltung=Bedingungen den Bedürfnissen anpassen"]],
 f:["F", "Erkläre die zwei Ziele der Sozialen Arbeit im Life Model an einem Beispiel.", "Bei einem einsamen Rentner stärkt die Sozialarbeit die Person (Selbstbild, Freizeit) und gestaltet die Umwelt (Kontakte, Treffpunkte)."]},
t12_3_14:{tz:"Begriff zuordnen",tf:"Begriff am Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Ressource=Familienhilfe, Wohnheim", "Nische=Rolle und Einfluss in Klasse oder Wohnheim", "anpassungsfeindliche Transaktion=Schulausschluss", "Ziel=Stärkung von Person und Gestaltung der Umwelt"]],
 f:["F", "Beschreibe, wie du den Fall Müller nach dem Life Model analysieren würdest.", "Ich beschreibe Frau Müller und Sebastian in ihren Umwelten (Familie, Schule, Wohnheim), prüfe Transaktionen, Nische, Habitat, Lebens-Stress, Coping, Ressourcen und leite Ziele für Person und Umwelt ab."]},
t12_3_15:{tz:"Begriff zuordnen",tf:"Begriff am Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Erklärungswert=Verhalten aus Person-Umwelt-Passung erklären", "Grenze=Probleme im Inneren der Person", "Kritik=unpräzise Begriffe", "Bereitschaft=Engagement der Betroffenen"]],
 f:["F", "Würdige das Life Model kurz (Erklärungswert, zwei Grenzen).", "Das Life Model erklärt Verhalten aus der Passung von Person und Umwelt und bezieht Umwelthilfen ein. Grenzen: Probleme im Inneren der Person und Umwelt, die sich nicht ändern lässt."]},
t12_3_16:{tz:"Begriff zuordnen",tf:"Begriff am Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Lebenswelt=Alltag des Menschen", "erfahrene Zeit=Erleben von Vergangenheit und Zukunft", "erfahrener Raum=Erleben des Lebensraums", "soziale Bezüge=Beziehungen zu anderen"]],
 f:["F", "Erkläre die Lebensweltorientierung nach Thiersch an einem Beispiel.", "Sie geht vom Alltag aus, z. B. Familie Kaya: Wohnung (Raum), Zukunftssorgen (Zeit), Kontakte (soziale Bezüge), Schulden (Bewältigungsaufgabe). Ziel ist Hilfe zur Selbsthilfe."]},
t12_3_17:{tz:"Maxime zuordnen",tf:"Maxime am Fall",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Prävention=Vorbeugen", "Alltagsnähe=Hilfe im Lebensumfeld", "Integration=Ausgrenzung verhindern", "Vernetzung=Zusammenarbeit von Hilfen"]],
 f:["F", "Nenne drei Maximen nach Thiersch und je ein Beispiel.", "Prävention: Aufklärung vor Sucht; Alltagsnähe: Sprechstunde im Park; Partizipation: Jugendbeirat."]},
t12_4_1:{tz:"Organon-Modell zuordnen",tf:"Begriffe abgrenzen",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Ausdruck (Symptom)=Das Zeichen zeigt etwas über den Sender", "Appell (Signal)=Das Zeichen wirkt auf den Empfänger", "Darstellung (Symbol)=Das Zeichen bezieht sich auf Gegenstände und Sachverhalte"]],
 f:["F", "Erkläre den Unterschied zwischen sozialer Kommunikation und sozialer Interaktion.", "Soziale Kommunikation ist der Austausch von Informationen zwischen Menschen. Soziale Interaktion ist das wechselseitige, aufeinander bezogene Handeln der Beteiligten."]},
t12_4_2:{tz:"Axiome zuordnen",tf:"Interpunktion am Beispiel",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["1. Axiom=Man kann nicht nicht kommunizieren", "2. Axiom=Jede Kommunikation hat einen Inhalts- und einen Beziehungsaspekt", "3. Axiom=Beteiligte legen unterschiedlich fest, was Ursache und was Wirkung ist"]],
 f:["F", "Erkläre das dritte Axiom (Interpunktion von Ereignisfolgen) an einem Beispiel.", "Beide Seiten gliedern den Ablauf unterschiedlich: Er zieht sich zurück, weil sie nörgelt – sie nörgelt, weil er sich zurückzieht. Jeder sieht nur das Verhalten des anderen als Ursache."]},
t12_4_3:{tz:"Modalitäten zuordnen",tf:"Komplementäre Beziehung",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Digitale Modalität=Sprache und Wörter", "Analoge Modalität=Mimik, Gestik und Tonfall", "Symmetrische Beziehung=Die Partner sind gleichberechtigt", "Komplementäre Beziehung=Die Rollen ergänzen sich, Unterschiede werden betont"]],
 f:["F", "Gib ein Beispiel für eine komplementäre Beziehung und erkläre, warum sie nicht automatisch schlecht ist.", "Beispiel: Erzieherin und Kind. Die Rollen ergänzen sich; das kann hilfreich sein, wenn die Rollenverteilung passt und beide sie akzeptieren."]},
t12_4_4:{tz:"Ich-Botschaft ordnen",tf:"Ich-Botschaft formulieren",
 z:["R", "Bringe die Bausteine einer Ich-Botschaft in eine sinnvolle Reihenfolge.", ["Das Verhalten sachlich beschreiben", "Das eigene Gefühl benennen", "Den Grund für das Gefühl nennen", "Einen Wunsch äußern"]],
 f:["F", "Formuliere eine Ich-Botschaft für die Situation: Ein Freund kommt zum dritten Mal zu spät.", "Ich ärgere mich, wenn du zu spät kommst, weil ich dann lange warten muss und unsere Zeit knapp wird. Ich wünsche mir, dass du Bescheid sagst, wenn es später wird."]},
t12_4_5:{tz:"Kulturelle Codes zuordnen",tf:"Missverständnis analysieren",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Normen und Werte=Zeigen, was in einer Kultur als richtig und angemessen gilt", "Verbale Codes=Sprache und Redewendungen", "Nonverbale Codes=Gestik, Mimik und Körperabstand", "Blickkontakt=Kann je nach Kultur Interesse oder Respektlosigkeit bedeuten"]],
 f:["F", "Nenne ein Beispiel für ein kulturbedingtes Missverständnis in der Kommunikation und wie man damit umgehen kann.", "Blickkontakt gilt in manchen Kulturen als Interesse, in anderen als respektlos. Man kann nachfragen und die eigene Deutung überprüfen, statt sofort zu urteilen."]},
t12_4_6:{tz:"Digitale Kommunikation zuordnen",tf:"Gefährdungen begegnen",
 z:["Z", "Ordne jedem Begriff die passende Beschreibung zu.", ["Cybermobbing=Wiederholtes Beleidigen oder Bloßstellen im Netz", "Datenmissbrauch=Persönliche Daten werden ohne Erlaubnis weitergegeben oder genutzt", "Fehlende nonverbale Signale=Mimik und Tonfall fehlen, Missverständnisse entstehen leichter"]],
 f:["F", "Nenne zwei Gefährdungen digitaler Kommunikation und eine Möglichkeit, ihnen zu begegnen.", "Cybermobbing und Datenmissbrauch. Man kann zum Beispiel Vorfälle melden und Vertrauenspersonen einbeziehen, sparsam mit persönlichen Daten umgehen und Privatsphäre-Einstellungen nutzen."]},
};
// Standard-Check-Ins (5 Fragen je Thema): 2 Multiple-Choice, 1 Aufgabe mit anderem Typ (Zuordnung/Lückentext/Reihenfolge), 1 K-Prim-Fall, 1 Freitext. Eine in Firebase gespeicherte Fassung hat Vorrang.
function checkinHash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
function checkinMischen(arr,key){return arr.map((x,i)=>({x,h:checkinHash(key+"|"+i+"|"+String(x))})).sort((p,q)=>p.h-q.h).map(o=>o.x)}
function checkinAusBank(id){
 const ende=/@ende$/.test(id);if(ende)id=id.slice(0,-5);const b=(ende?CHECKOUT_12:CHECKIN_12)[id];if(!b)return[];
 const n=CHECKIN_NEU[id],t=CHECKIN_TAGS_12[id]||[];
 let items,tags,ph;
 if(ende){
  // Check-out (anspruchsvoller, mit Transfer): Sichern, Anwenden, Erklären und Begründen, danach der Rückblick (Sicherheit + Lernkurve)
  items=b;tags=n?[t[0],t[1],n.tz,t[4],n.tf]:t;
  ph=["Sichern","Sichern","Sichern","Anwenden","Erklären und begründen"];
 }else{
  // Check-in (leicht): Hinführung, Vorwissen, eigene Fragen
  const k=b.find(q=>q[0]==="K");
  items=[k?["I",k[1]]:null,b[0],b[1],n?n.z:b[2],["E"]];
  tags=["Hinführung",t[0],t[1],n?n.tz:t[2],"Eigene Fragen"];
  ph=["Hinführung","Vorwissen","Vorwissen","Vorwissen","Eigene Fragen"];
 }
 const out=items.map((q,qi)=>{
  if(!q)return null;
  const tag=tags[qi]||"";
  if(q[0]==="I")return{typ:"frei",opt:true,text:"Lies die Situation. Was fällt dir auf? Was weißt du schon dazu?",situation:q[1],tag,platzhalter:"Schreibe auf, was dir auffällt. Auch Vermutungen sind willkommen …",hinweis:"Diese Aufgabe wird nicht bewertet. Es gibt keine falsche Antwort."};
  if(q[0]==="E")return{typ:"frei",opt:true,text:"Welche Fragen hast du zu diesem Thema? Was möchtest du noch wissen?",tag,platzhalter:"Schreibe deine Fragen auf …",hinweis:"Deine Fragen helfen dir und deiner Lehrkraft. Sie werden nicht bewertet."};
  if(q[0]==="K")return{typ:"kprim",text:q[1],tag,statements:q[2].map(s=>({text:s.slice(1),correct:s[0]==="+"}))};
  if(q[0]==="Z")return{typ:"zuordnung",text:q[1],tag,paare:q[2].map(p=>{const k=p.indexOf("=");return{l:p.slice(0,k),r:p.slice(k+1)}})};
  if(q[0]==="L")return{typ:"lueckentext",text:q[1],tag,loesung:q[2],woerter:checkinMischen(q[2].concat(q[3]||[]),q[1])};
  if(q[0]==="R")return{typ:"reihenfolge",text:q[1],tag,schritte:q[2]};
  if(q[0]==="F")return{typ:"frei",text:q[1],tag,musterantwort:q[2]};
  const opts=q.slice(1).map((t,i)=>({t,r:i===0}));
  const k=checkinHash(q[0])%opts.length;
  const o=opts.slice(k).concat(opts.slice(0,k));
  return{typ:"mc",text:q[0],tag,optionen:o.map(x=>x.t),richtig:o.findIndex(x=>x.r)};
 });
 return out.map((o,qi)=>o?{...o,phase:ph[qi]}:o).filter(Boolean);
}
async function getBasischeckFragen(wocheId){
 try{
 const snap=await getDoc(doc(db,"basischeckFragen",wocheId));
 if(snap.exists()&&snap.data().v===2&&(snap.data().fragen||[]).length)return snap.data().fragen;
 return checkinAusBank(wocheId);
 }catch(e){console.error("Check-in-Fragen laden:",e);return checkinAusBank(wocheId)}
}
function basischeckTypToggle(i){
 const typ=$(`bcTyp${i}`)?.value;
 const m={mc:"bcMcBereich",kprim:"bcKprimBereich",offen:"bcOffenBereich",zuordnung:"bcZBereich",lueckentext:"bcLBereich",reihenfolge:"bcRBereich",frei:"bcFBereich"};
 Object.keys(m).forEach(k=>{const el=$(`${m[k]}${i}`);if(el)el.style.display=typ===k?"block":"none"});
 const ka=$(`bcKarte${i}`);if(ka){ka.className=ka.className.replace(/\s*ci-k-\w+/g,"")+" ci-k-"+typ}
}
window.basischeckTypToggle=basischeckTypToggle;
async function saveBasischeckFragen(fach,wocheId){
 if(!isTeacher()){toast("Nur Lehrkräfte können Check-in-Fragen anlegen.");return}
 const fragen=[];
 for(let i=0;i<5;i++){
 const text=$(`bcFrage${i}`)?.value.trim();
 if(!text)continue;
 const typ=$(`bcTyp${i}`)?.value||"mc";
 const tag=($(`bcTag${i}`)?.value||"").trim();
 if(typ==="mc"){
 const opts=[0,1,2].map(j=>$(`bcOpt${i}_${j}`)?.value.trim()).filter(Boolean);
 const richtig=parseInt($(`bcRichtig${i}`)?.value,10);
 if(opts.length<2||!Number.isFinite(richtig))continue;
 fragen.push({typ,text,...(tag?{tag}:{}),optionen:opts,richtig});
 }else if(typ==="kprim"){
 const statements=[0,1,2,3].map(j=>({
 text:$(`bcStatement${i}_${j}`)?.value.trim()||"",
 correct:$(`bcStatementRichtig${i}_${j}`)?.value==="true"
 })).filter(s=>s.text);
 if(statements.length<2)continue;
 const vignette=$(`bcVignette${i}`)?.value.trim()||"";
 fragen.push({typ,text,...(tag?{tag}:{}),statements,...(vignette?{vignette}:{})});
 }else if(typ==="offen"){
 const stichworte=($(`bcStichworte${i}`)?.value||"").split(",").map(s=>s.trim()).filter(Boolean);
 if(!stichworte.length)continue;
 fragen.push({typ,text,...(tag?{tag}:{}),stichworte});
 }else if(typ==="zuordnung"){
 const paare=($(`bcPaare${i}`)?.value||"").split("\n").map(z=>{const k=z.indexOf("=");return k>0?{l:z.slice(0,k).trim(),r:z.slice(k+1).trim()}:null}).filter(p=>p&&p.l&&p.r).slice(0,5);
 if(paare.length<2){toast(`Frage ${i+1}: Zuordnung braucht mindestens 2 Zeilen der Form „Begriff = Beschreibung“.`);continue}
 fragen.push({typ,text,...(tag?{tag}:{}),paare});
 }else if(typ==="lueckentext"){
 const loesung=($(`bcLoesung${i}`)?.value||"").split(",").map(x=>x.trim()).filter(Boolean);
 const extra=($(`bcExtra${i}`)?.value||"").split(",").map(x=>x.trim()).filter(Boolean);
 const luecken=(text.match(/___/g)||[]).length;
 if(!luecken||luecken!==loesung.length){toast(`Frage ${i+1}: Der Text braucht genau so viele ___ wie gesuchte Wörter (${loesung.length}).`);continue}
 fragen.push({typ,text,...(tag?{tag}:{}),loesung,woerter:checkinMischen(loesung.concat(extra),text)});
 }else if(typ==="reihenfolge"){
 const schritte=($(`bcSchritte${i}`)?.value||"").split("\n").map(x=>x.trim()).filter(Boolean).slice(0,6);
 if(schritte.length<3){toast(`Frage ${i+1}: Reihenfolge braucht mindestens 3 Schritte (je eine Zeile, in richtiger Reihenfolge).`);continue}
 fragen.push({typ,text,...(tag?{tag}:{}),schritte});
 }else if(typ==="frei"){
 fragen.push({typ,text,...(tag?{tag}:{}),musterantwort:($(`bcMuster${i}`)?.value||"").trim()});
 }
 }
 if(!fragen.length){toast("Bitte mindestens eine vollständige Frage eingeben.");return}
 try{
 await setDoc(doc(db,"basischeckFragen",wocheId),{wocheId,fach,fragen,v:2,updatedAt:serverTimestamp(),updatedBy:currentUser.uid});
 toast("Check-in gespeichert.");
 if($("ciAnsicht")){await openCheckIn(wocheId);return}
 await reopenDetail(fach,wocheId);
 }catch(e){console.error("Check-in speichern:",e);toast(e?.code==="permission-denied"?"Firebase verweigert das Speichern. Bitte die Firestore-Regeln prüfen.":"Konnte nicht gespeichert werden.");}
}
window.saveBasischeckFragen=saveBasischeckFragen;
async function getMyBasischeckVersuch(wocheId){
 try{
 const snap=await getDoc(doc(db,"basischeckVersuche",`${currentUser.uid}_${wocheId}`));
 return snap.exists()?snap.data():null;
 }catch(e){console.error("Check-in-Versuch laden:",e);return null}
}
// ---- Check-in-Verlauf: alle Versuche stehen im selben Datensatz (verlauf), kein Zusatz-Laden ----
function ciVerlauf(x){
 const v=Array.isArray(x&&x.verlauf)?x.verlauf.filter(p=>p&&p.g>0):[];
 if(v.length)return v;
 return x&&x.gesamt>0?[{r:x.richtig,g:x.gesamt}]:[];
}
function ciProz(p){return Math.round(p.r/p.g*100)}
function ciVerlaufTxt(x){const v=ciVerlauf(x);return v.length>1?v.map(p=>ciProz(p)+" %").join(" → "):""}
function ciVerlaufSVG(x){
 const v=ciVerlauf(x);if(v.length<2)return"";
 const W=352,H=176,L=54,R=314,T=16,B=132,n=v.length;
 const px=i=>L+(R-L)*i/(n-1),py=q=>B-(B-T)*q/100;
 const band=(a,b,c)=>`<rect x="${L}" y="${py(b).toFixed(1)}" width="${R-L}" height="${(py(a)-py(b)).toFixed(1)}" fill="${c}"/>`;
 const pts=v.map((p,i)=>[px(i),py(ciProz(p))]);
 const lab=v.map((p,i)=>{
  const dt=p.t?new Date(p.t):null,ds=dt?`${dt.getDate()}.${dt.getMonth()+1}.`:"";
  return`<text x="${px(i).toFixed(1)}" y="${(pts[i][1]-8).toFixed(1)}" text-anchor="middle" font-size="11" fill="#1f2d3d">${ciProz(p)} %</text>`
   +`<text x="${px(i).toFixed(1)}" y="${B+16}" text-anchor="middle" font-size="10.5" fill="#3a4a5a">${i===0?"Start":"Wdh. "+i}</text>`
   +(ds?`<text x="${px(i).toFixed(1)}" y="${B+29}" text-anchor="middle" font-size="9.5" fill="#7a8794">${ds}</text>`:"");
 }).join("");
 const ticks=[0,50,100].map(q=>`<text x="${L-6}" y="${(py(q)+3.5).toFixed(1)}" text-anchor="end" font-size="10" fill="#7a8794">${q}</text>`).join("");
 return`<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Verlauf: ${ciVerlaufTxt(x)}">${band(0,40,"#F7E3E3")}${band(40,75,"#FAF2DC")}${band(75,100,"#E1EEE6")}${ticks}<polyline fill="none" stroke="#1F3A60" stroke-width="2.4" stroke-linejoin="round" points="${pts.map(q=>q[0].toFixed(1)+","+q[1].toFixed(1)).join(" ")}"/>${pts.map(q=>`<circle cx="${q[0].toFixed(1)}" cy="${q[1].toFixed(1)}" r="4.2" fill="#1F3A60"/>`).join("")}${lab}</svg>`;
}
function basischeckAmpel(richtig,gesamt){
 if(gesamt<=0)return null;
 const q=richtig/gesamt;
 if(q>=0.75)return"gruen";
 if(q>=0.4)return"orange";
 return"rot";
}
function basischeckAmpelText(ampel){
 if(ampel==="gruen")return"Grün – die Basis sitzt schon";
 if(ampel==="orange")return"Gelb – ein Teil sitzt schon, lies den Lehrtext gezielt";
 if(ampel==="rot")return"Rot – das Thema ist neu, der Lehrtext hilft dir";
 return"Noch nicht bearbeitet";
}
// Wertet eine einzelne Check-in-Frage aus, je nach Typ. Alte Fragen ohne
// "typ"-Feld werden wie Multiple Choice behandelt (Rückwärtskompatibilität).
function basischeckGradeFrage(f,i){
 const typ=f.typ||"mc";
 if(typ==="mc"){
 const antwort=parseInt(document.querySelector(`input[name="bcQ${i}"]:checked`)?.value,10);
 return {beantwortet:Number.isFinite(antwort),richtig:antwort===f.richtig,antwort};
 }
 if(typ==="kprim"){
 const werte=f.statements.map((s,j)=>document.querySelector(`input[name="bcKp${i}_${j}"]:checked`)?.value||"");
 const alleBeantwortet=werte.every(Boolean);
 const {allCorrect}=kprimGrade({statements:f.statements},werte.map(w=>w==="r"));
 // als Text speichern ("rfrf"), weil Firestore keine verschachtelten Listen erlaubt
 return {beantwortet:alleBeantwortet,richtig:alleBeantwortet&&allCorrect,antwort:werte.map(w=>w||"-").join("")};
 }
 if(typ==="offen"){
 const text=($(`bcOffenAntwort${i}`)?.value||"").trim();
 if(!text)return{beantwortet:false,richtig:false,antwort:""};
 const treffer=f.stichworte.every(w=>text.toLowerCase().includes(w.toLowerCase()));
 return {beantwortet:true,richtig:treffer,antwort:text};
 }
 if(typ==="zuordnung"){
 const w=f.paare.map((p,j)=>document.querySelector(`#bcZ${i}_${j}`)?.value||"");
 const ok=w.every(Boolean);
 return {beantwortet:ok,richtig:ok&&w.every((v,j)=>v===String(j)),antwort:w.map(v=>v===""?"-":v).join(",")};
 }
 if(typ==="lueckentext"){
 const w=f.loesung.map((l,j)=>document.querySelector(`#bcL${i}_${j}`)?.value||"");
 const ok=w.every(Boolean);
 return {beantwortet:ok,richtig:ok&&w.every((v,j)=>v===f.loesung[j]),antwort:w.map(v=>v||"-").join("|")};
 }
 if(typ==="reihenfolge"){
 const w=f.schritte.map((x,j)=>document.querySelector(`#bcR${i}_${j}`)?.value||"");
 const ok=w.every(Boolean)&&new Set(w).size===w.length;
 return {beantwortet:ok,richtig:ok&&w.every((v,j)=>v===String(j+1)),antwort:w.map(v=>v||"-").join(",")};
 }
 if(typ==="frei"){
 const text=($(`bcFrei${i}`)?.value||"").trim();
 return {beantwortet:!!f.opt||text.length>=10,richtig:false,antwort:text,frei:true};
 }
 return {beantwortet:false,richtig:false,antwort:null};
}
async function submitBasischeck(e,t){const n=await getBasischeckFragen(t);if(!n.length){toast("Keine Fragen vorhanden.");return}const i=n.map((d,p)=>basischeckGradeFrage(d,p)),r=i.findIndex(d=>!d.beantwortet);if(r>=0){toast(n[r].typ==="frei"?"Bitte schreibe bei der Freitext-Aufgabe mindestens einen Satz.":"Bitte alle Fragen beantworten.");return}const a=i.filter(d=>!d.frei),s=a.filter(d=>d.richtig).length,l=a.length,c=basischeckAmpel(s,l);try{const d=await getMyBasischeckVersuch(t),p=parseInt(document.querySelector('input[name="ciSich"]:checked')?.value,10)||0,h=d&&d.createdAt&&d.createdAt.toMillis?d.createdAt.toMillis():0,k=[...d?d.verlauf||[{r:d.richtig,g:d.gesamt,s:d.sicher||0,t:h}]:[],{r:s,g:l,s:p,t:Date.now(),rf:i.map(f=>f.frei?"x":f.richtig?"1":"0").join("")}].slice(-10);if(await setDoc(doc(db,"basischeckVersuche",`${currentUser.uid}_${t}`),{uid:currentUser.uid,wocheId:t,fach:e,antworten:i.map(f=>f.antwort),tg:n.map(f=>f.tag||""),richtig:s,gesamt:l,ampel:c,sicher:p,verlauf:k,name:anzeigeName(profile,currentUser),createdAt:serverTimestamp()}),delete CI_NEU[t],toast(`${s} von ${l} richtig.`),$("ciAnsicht")){(/@ende$/.test(t)||await setDoc(doc(db,"lehrplanFortschritt",`${currentUser.uid}_${t}`),{uid:currentUser.uid,wocheId:t,fach:e,basischeckErledigt:!0,updatedAt:serverTimestamp()},{merge:!0}).catch(f=>console.error(f))),ppDirty=!0,await openCheckIn(t),c==="gruen"&&showMotivationsBild(!1,"lernen","bc:"+t);return}if(lehrplanWocheById(e,t)?.typ==="apt"){await aptSetzen(t,{basischeckErledigt:!0},{tab:"basischeck"});return}(/@ende$/.test(t)||await setDoc(doc(db,"lehrplanFortschritt",`${currentUser.uid}_${t}`),{uid:currentUser.uid,wocheId:t,fach:e,basischeckErledigt:!0,updatedAt:serverTimestamp()},{merge:!0}).catch(f=>console.error(f))),await reopenDetail(e,t),c==="gruen"&&showMotivationsBild(!1,"lernen","bc:"+t)}catch(d){console.error("Check-in abgeben:",d),toast(d?.code==="permission-denied"?"Firebase verweigert das Speichern. Bitte die Firestore-Regeln pr\xFCfen.":"Konnte nicht gespeichert werden.")}}
window.submitBasischeck=submitBasischeck;

// ---- Live-Wochenübersicht für Lehrkräfte: Fortschritt-Position je Person,
// Check-in-Ampel, Lernstand-Ampel und "zuletzt aktiv" – aktualisiert sich
// automatisch per Firestore-Live-Listener, ohne dass neu geöffnet werden muss.
let wochenLiveState=null;
function renderWochenLiveTable(fach,wocheId,woche){
 const st=wochenLiveState;
 if(!st)return;
 const tbody=$("wochenLiveTbody");
 if(!tbody)return;
 const relevanteTasks=st.lsTasks.filter(t=>st.wocheLbKeys.includes(t.learningArea));
 // Basis-Schritte, die immer zählen: Auftrag, Material, Lernprodukt, Lernstand, Selbsteinschätzung.
 // Check-in und Team zählen nur mit, wenn für diese Woche zutreffend.
 const gesamtSchritte=5+(st.hatBasischeck?1:0)+(wocheHatTeam(woche)?1:0)+(woche.interaktiv?1:0);
 tbody.innerHTML=st.students.map(s=>{
 const f=st.fortschritt.find(x=>x.uid===s.uid)||{};
 const bc=st.basischeck.find(x=>x.uid===s.uid);
 const team=st.teams.some(t=>(t.mitgliederUids||[]).includes(s.uid));
 const produkt=st.produkte.some(p=>p.uid===s.uid);
 const lernstandOk=relevanteTasks.some(t=>st.lsAttempts.some(a=>a.uid===s.uid&&a.taskId===t.id));
 let position=0;
 if(f.auftragGelesen)position++;
 if(f.materialErhalten)position++;
 if(st.hatBasischeck&&bc)position++;
 if(wocheHatTeam(woche)&&team)position++;
 if(woche.interaktiv&&f.experimentErledigt)position++;
 if(produkt)position++;
 if(lernstandOk)position++;
 const zieleErfuellt=st.ziele.length>0&&st.ziele.every(z=>f.zieleErfuellt?.[z.id]);
 if(zieleErfuellt)position++;
 const letzteAktivitaet=f.updatedAt?.seconds?new Date(f.updatedAt.seconds*1000):null;
 const tageInaktiv=letzteAktivitaet?Math.floor((Date.now()-letzteAktivitaet.getTime())/86400000):null;
 return`<tr>
 <td>${esc(anzeigeName(s))}</td>
 <td>${position} / ${gesamtSchritte}</td>
 <td style="text-align:center">${st.hatBasischeck?praktikumsAmpelDotHTMLGeneric(bc?.ampel,bc?basischeckAmpelText(bc.ampel):"Noch nicht bearbeitet"):"–"}</td>
 <td style="text-align:center">${relevanteTasks.length?ampelDotHTML(lernstandOk?lernstandStatus((st.lsAttempts.find(a=>a.uid===s.uid&&relevanteTasks.some(t=>t.id===a.taskId))?.total)||0,relevanteTasks.length?lernstandMaxPoints(relevanteTasks[0].id):15):null):"–"}</td>
 <td style="font-size:11px;color:${tageInaktiv!==null&&tageInaktiv>=3?"#d9534f":"var(--muted)"}">${letzteAktivitaet?letzteAktivitaet.toLocaleDateString("de-DE"):"noch nicht begonnen"}</td>
 </tr>`;
 }).join("")||`<tr><td colspan="5">Keine Schüler:innen gefunden.</td></tr>`;
}
function praktikumsAmpelDotHTMLGeneric(ampel,titel){
 if(!ampel)return`<span class="ampel-dot ampel-none"title="${esc(titel||"Noch offen")}"></span>`;
 return`<span class="ampel-dot"style="background:${ampelFarbe(ampel)}"title="${esc(titel||"")}"></span>`;
}
function subscribeWochenLive(fach,wocheId,woche){
 const u1=onSnapshot(
 query(collection(db,"lehrplanFortschritt"),where("wocheId","==",wocheId)),
 snap=>{wochenLiveState.fortschritt=snap.docs.map(d=>d.data());renderWochenLiveTable(fach,wocheId,woche);},
 e=>console.error("Wochen-Live-Update (Fortschritt):",e)
 );
 const u2=onSnapshot(
 query(collection(db,"basischeckVersuche"),where("wocheId","==",wocheId)),
 snap=>{wochenLiveState.basischeck=snap.docs.map(d=>d.data());renderWochenLiveTable(fach,wocheId,woche);},
 e=>console.error("Wochen-Live-Update (Check-in):",e)
 );
 liveUnsubscribe=()=>{try{u1();}catch(e){}try{u2();}catch(e){}};
}
async function openWochenLiveUebersicht(fach,wocheId){
 if(!isTeacher()){toast("Nur Lehrkräfte können die Live-Übersicht öffnen.");return}
 const woche=lehrplanWocheById(fach,wocheId);
 if(!woche){toast("Diese Woche wurde nicht gefunden.");return}
 let students=[],teams=[],produkte=[],lsTasks=[],lsAttempts=[],basischeckFragen=[];
 try{
 [students,teams,produkte,lsTasks,lsAttempts,basischeckFragen]=await Promise.all([
 getAllUsersForLernstand(),getLehrplanTeams(teamAnchorFor(wocheId)),getLehrplanProdukte(wocheId),
 getLernstandTasks(),getAllLernstandAttempts(),getBasischeckFragen(wocheId)
 ]);
 }catch(e){console.error("Live-Übersicht laden:",e);toast("Konnte nicht geladen werden.");return}
 const wocheLbKeys=(woche.lb||"").match(/\d/g)?.map(n=>"lb"+n)||[];
 const ziele=(LEHRPLAN_ZIELE_VORSCHLAG[wocheId]||[]).map((text,i)=>({id:`z${i}`,text}));
 wochenLiveState={students,teams,produkte,lsTasks,lsAttempts,wocheLbKeys,ziele,fortschritt:[],basischeck:[],hatBasischeck:basischeckFragen.length>0};
 modal(`<button class="modal-close"onclick="closeModal()">×</button>
 <div class="kicker"> LIVE-ÜBERSICHT · NUR LEHRKRÄFTE</div>
 <h2>${esc(woche.thema)}</h2>
 <p style="color:var(--muted);font-size:12px">Aktualisiert sich automatisch, sobald Schüler:innen einen Schritt abschließen – kein Neuladen nötig. Rot markiertes Datum = seit 3+ Tagen keine Aktivität.</p>
 <div style="overflow-x:auto"><table class="ls-matrix">
 <thead><tr><th>Schüler:in</th><th>Fortschritt</th><th>Check-in</th><th>Abschluss-Check</th><th>Zuletzt aktiv</th></tr></thead>
 <tbody id="wochenLiveTbody"><tr><td colspan="5">Lädt …</td></tr></tbody>
 </table></div>
 <div class="form-actions"style="margin-top:14px">
 <button class="primary"onclick="openAbschlussCheckQualitaet('${fach}','${wocheId}')"> Qualitäts-Ansicht Abschluss-Check</button>
 <button class="secondary"onclick="closeModal()">Schließen</button>
 </div>
 `);
 renderWochenLiveTable(fach,wocheId,woche);
 subscribeWochenLive(fach,wocheId,woche);
}
window.openWochenLiveUebersicht=openWochenLiveUebersicht;

// ---- Qualitäts-Ansicht Abschluss-Check: nicht nur wer bestanden hat, sondern
// echte fachliche Auswertung – Klassenschnitt, Punkte je Person, und welche
// einzelne Teilaufgabe der Klasse am schwersten fiel.
async function openAbschlussCheckQualitaet(fach,wocheId){
 if(!isTeacher()){toast("Nur Lehrkräfte können die Qualitäts-Ansicht öffnen.");return}
 const woche=lehrplanWocheById(fach,wocheId);
 if(!woche){toast("Diese Woche wurde nicht gefunden.");return}
 let students=[],lsTasks=[],lsAttempts=[];
 try{
 [students,lsTasks,lsAttempts]=await Promise.all([getAllUsersForLernstand(),getLernstandTasks(),getAllLernstandAttempts()]);
 }catch(e){console.error("Qualitäts-Ansicht laden:",e);toast("Konnte nicht geladen werden.");return}
 const wocheLbKeys=(woche.lb||"").match(/\d/g)?.map(n=>"lb"+n)||[];
 const relevanteTasks=lsTasks.filter(t=>wocheLbKeys.includes(t.learningArea));
 if(!relevanteTasks.length){
 modal(`<button class="modal-close"onclick="closeModal()">×</button>
 <div class="kicker">QUALITÄTS-ANSICHT · ABSCHLUSS-CHECK</div><h2>${esc(woche.thema)}</h2>
 <div class="empty">Für diese Woche ist keine Lernstandsmessung hinterlegt.</div>`);
 return;
 }
 // Je Person und Aufgabe nur den jeweils letzten Versuch werten.
 const zeilen=students.map(s=>{
 const proAufgabe=relevanteTasks.map(t=>lernstandLatest(lsAttempts.filter(a=>a.uid===s.uid),t.id));
 const bearbeitet=proAufgabe.filter(Boolean);
 const summe=bearbeitet.reduce((sum,a)=>sum+(Number(a.total)||0),0);
 const max=relevanteTasks.reduce((sum,t)=>sum+lernstandMaxPoints(t.id),0);
 return {name:anzeigeName(s),summe,max,bearbeitet:bearbeitet.length,gesamt:relevanteTasks.length,attempts:bearbeitet};
 });
 const bearbeiteteZeilen=zeilen.filter(z=>z.bearbeitet>0);
 const klassenschnitt=bearbeiteteZeilen.length?(bearbeiteteZeilen.reduce((s,z)=>s+z.summe,0)/bearbeiteteZeilen.length):0;
 const maxGesamt=relevanteTasks.reduce((sum,t)=>sum+lernstandMaxPoints(t.id),0);

 // Pro Teilkompetenz (z. B. Fachwissen, Anwenden, Analysieren) den
 // Klassenschnitt berechnen, um Schwachstellen im Stoff sichtbar zu machen.
 const teilaufgaben=[];
 relevanteTasks.forEach(t=>{
 (t.tasks||[]).forEach(sub=>{
 const werte=[];
 students.forEach(s=>{
 const latest=lernstandLatest(lsAttempts.filter(a=>a.uid===s.uid),t.id);
 if(latest?.competencies?.[sub.id]!==undefined)werte.push(Number(latest.competencies[sub.id])||0);
 });
 if(werte.length){
 const schnitt=werte.reduce((a,b)=>a+b,0)/werte.length;
 teilaufgaben.push({label:`${t.nr}. ${t.title} – ${sub.label}`,schnitt,max:sub.points,quote:schnitt/(sub.points||1),anzahl:werte.length});
 }
 });
 });
 teilaufgaben.sort((a,b)=>a.quote-b.quote);

 modal(`<button class="modal-close"onclick="closeModal()">×</button>
 <div class="kicker">QUALITÄTS-ANSICHT · ABSCHLUSS-CHECK</div>
 <h2>${esc(woche.thema)}</h2>
 <div class="card"style="border-left:4px solid #4a90d9;margin:10px 0 16px">
 <strong style="font-size:20px">Ø ${klassenschnitt.toFixed(1)} von ${maxGesamt} Punkten</strong>
 <p style="margin:4px 0 0;color:var(--muted);font-size:12px">${bearbeiteteZeilen.length} von ${students.length} haben bereits bearbeitet.</p>
 </div>

 <h3 style="margin-bottom:6px"> Wo die Klasse noch Schwierigkeiten hat</h3>
 <div class="list"style="margin-bottom:16px">
 ${teilaufgaben.slice(0,5).map(t=>{
 const farbe=t.quote>=0.8?"#3fa66a":t.quote>=0.53?"#e0a324":"#d9534f";
 return`<div class="list-item"><div><strong>${esc(t.label)}</strong><small>Klassenschnitt: ${t.schnitt.toFixed(1)} von ${t.max} Punkten (${Math.round(t.quote*100)}%), ${t.anzahl} Bearbeitungen</small></div><span class="pill"style="background:${farbe};color:#fff">${Math.round(t.quote*100)}%</span></div>`;
 }).join("")||`<div class="empty">Noch keine ausreichenden Daten.</div>`}
 </div>

 <h3 style="margin-bottom:6px"> Punkte je Person</h3>
 <div class="list">
 ${zeilen.map(z=>{
 const pct=z.max?z.summe/z.max:0;
 const farbe=z.bearbeitet===0?"#c7d0d6":pct>=0.8?"#3fa66a":pct>=0.53?"#e0a324":"#d9534f";
 return`<div class="list-item"><div><strong>${esc(z.name)}</strong></div><span class="pill"style="background:${farbe};color:#fff">${z.bearbeitet===0?"noch offen":`${z.summe.toFixed(0)}/${z.max} (${z.bearbeitet}/${z.gesamt} Aufgaben)`}</span></div>`;
 }).join("")}
 </div>
 <div class="form-actions"style="margin-top:14px"><button class="secondary"onclick="closeModal()">Schließen</button></div>
 `);
}
window.openAbschlussCheckQualitaet=openAbschlussCheckQualitaet;

// ---- Phasen-Live-Übersicht: zwei parallele Signale je Person – wie weit sie
// mit den notwendigen Wochen-Inhalten ist (Ampel A) und wo ihr Team beim
// Projekt steht (Ampel B, aus den projektspezifischen Meilensteinen).
let phasenLiveState=null;
function inhaltsAmpelFarbe(fertig,gesamt){
 if(gesamt===0)return"#c7d0d6";
 if(fertig===0)return"#c7d0d6";
 if(fertig===gesamt)return"#3fa66a";
 return"#e0a324";
}
function renderPhasenLiveTable(phase){
 const st=phasenLiveState;
 if(!st)return;
 const tbody=$("phasenLiveTbody");
 if(!tbody)return;
 tbody.innerHTML=st.students.map(s=>{
 const fertigeWochen=phase.notwendigeWochen.filter(wId=>
 st.fortschritt.some(f=>f.uid===s.uid&&f.wocheId===wId&&f.abgeschlossen)
 ).length;
 const team=st.teams.find(t=>(t.mitgliederUids||[]).includes(s.uid));
 const idx=msErreichtAnzahl(phase,team,st.beitraege);
 const nx=team?msNaechster(phase,team,st.beitraege):null;
 const eig=msEigeneBeitraege(phase,team,st.beitraege,s.uid);
 const stundeFertig=phase.einstieg&&st.fortschritt.some(f=>f.uid===s.uid&&f.wocheId===phase.stundeWocheId&&f.experimentErledigt);
 const meilensteinLabel=phase.einstieg?(stundeFertig?"interaktive Stunde gemacht":"interaktive Stunde noch offen"):!team?"kein Team":!nx?"alle Meilensteine erreicht":`nächster: ${phase.meilensteine[nx.i]} (${MS_ZUSTAND[nx.st.zustand].t}) · eigene Beiträge ${eig.n}/${eig.g}`;
 const letzteAktivitaet=st.fortschritt.filter(f=>f.uid===s.uid&&phase.notwendigeWochen.includes(f.wocheId))
 .map(f=>f.updatedAt?.seconds?new Date(f.updatedAt.seconds*1000):null).filter(Boolean).sort((a,b)=>b-a)[0];
 const tageInaktiv=letzteAktivitaet?Math.floor((Date.now()-letzteAktivitaet.getTime())/86400000):null;
 return`<tr>
 <td>${esc(anzeigeName(s))}</td>
 <td style="text-align:center"><span class="ampel-dot"style="background:${inhaltsAmpelFarbe(fertigeWochen,phase.notwendigeWochen.length)}"title="${fertigeWochen} von ${phase.notwendigeWochen.length} notwendigen Wochen"></span> ${fertigeWochen}/${phase.notwendigeWochen.length}</td>
 <td style="text-align:center"><span class="ampel-dot"style="background:${phase.einstieg?(stundeFertig?"#3fa66a":"#c7d0d6"):meilensteinAmpelFarbe(idx,phase.meilensteine.length)}"title="${esc(meilensteinLabel)}"></span></td>
 <td style="font-size:12px;color:var(--muted)">${esc(phase.einstieg?"–":(team?.teamName||"kein Team"))}</td>
 <td style="font-size:11px">${esc(meilensteinLabel)}</td>
 <td style="font-size:11px;color:${tageInaktiv!==null&&tageInaktiv>=3?"#d9534f":"var(--muted)"}">${letzteAktivitaet?letzteAktivitaet.toLocaleDateString("de-DE"):"noch nicht begonnen"}</td>
 </tr>`;
 }).join("")||`<tr><td colspan="6">Keine Schüler:innen gefunden.</td></tr>`;
}
function subscribePhasenLive(phase){
 const u1=onSnapshot(
 query(collection(db,"lehrplanFortschritt"),where("wocheId","in",phase.notwendigeWochen.length?phase.notwendigeWochen:["_none_"])),
 snap=>{phasenLiveState.fortschritt=snap.docs.map(d=>d.data());renderPhasenLiveTable(phase);},
 e=>console.error("Phasen-Live-Update:",e)
 );
 const u2=onSnapshot(
 query(collection(db,"lehrplanTeams"),where("wocheId","==",phase.projektWocheId)),
 snap=>{phasenLiveState.teams=snap.docs.map(d=>({id:d.id,...d.data()}));renderPhasenLiveTable(phase);},
 e=>console.error("Phasen-Live-Update (Teams):",e)
 );
 liveUnsubscribe=()=>{try{u1();}catch(e){}try{u2();}catch(e){}};
}
async function openPhasenLiveUebersicht(phaseId){
 if(!isTeacher()){toast("Nur Lehrkräfte können die Live-Übersicht öffnen.");return}
 const phase=projektPhaseById(phaseId);
 if(!phase){toast("Diese Phase wurde nicht gefunden.");return}
 let students=[],teams=[];
 try{
 students=await getAllUsersForLernstand();
 teams=await getLehrplanTeams(phase.projektWocheId);
 }catch(e){console.error("Phasen-Live-Übersicht laden:",e);toast("Konnte nicht geladen werden.");return}
 phasenLiveState={students,teams,fortschritt:[],beitraege:await getMeilensteinBeitraege(teams.map(t=>t.id))};
 modal(`<button class="modal-close"onclick="closeModal()">×</button>
 <div class="kicker"> LIVE-ÜBERSICHT · ${esc(phase.lb)} · NUR LEHRKRÄFTE</div>
 <h2>${esc(phase.titel)}</h2>
 <p style="color:var(--muted);font-size:12px">Zwei Signale: links der Inhalts-Fortschritt (notwendige Wochen), rechts der Projekt-Meilenstein des Teams. Aktualisiert sich automatisch. Rot markiertes Datum = seit 3+ Tagen keine Aktivität.</p>
 <div style="overflow-x:auto"><table class="ls-matrix">
 <thead><tr><th>Schüler:in</th><th>Inhalt</th><th>Projekt</th><th>Team</th><th>Meilenstein</th><th>Zuletzt aktiv</th></tr></thead>
 <tbody id="phasenLiveTbody"><tr><td colspan="6">Lädt …</td></tr></tbody>
 </table></div>
 <div class="form-actions"style="margin-top:14px"><button class="secondary"onclick="closeModal()">Schließen</button></div>
 `);
 renderPhasenLiveTable(phase);
 subscribePhasenLive(phase);
}
window.openPhasenLiveUebersicht=openPhasenLiveUebersicht;

