function wbIcon(n,sz){sz=sz||22;return`<svg viewBox="0 0 24 24" width="${sz}" height="${sz}" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${WB_ICONS[n]||""}</svg>`;}

