let __campusRenderSeq=0;
// ---- Navigation: Verlauf und „Zurück“-Button auf jeder Seite ----
// Jede Seite (Schüler und Lehrkräfte) bekommt oben einen „← Zurück“-Knopf, der zur vorherigen Ebene bzw. Funktion führt.
// Eigene Zurück-Knöpfe einer Seite (z. B. „← Unterricht“) bleiben erhalten; dann wird kein zweiter Knopf eingefügt.
let NAV_STACK=[],NAV_CUR=null,NAV_SKIP=false;
function navSnap(p){return{p,a:activeBoardId,b:activeFach,c:activePhaseDetail,d:activePPModul,e:activeWhiteboardId,f:activeWordcloudId,g:activeKanbanId,h:activeTermPollId,i:activeChecklistId,j:activeAmpelId,k:activePollId,l:activeZuordnungId,m:activeDeckId,n:activeEssayCaseId,o:activeConversationUid,q:activeConversationName,r:activeKwThema,t:activeKwLb};}
function navVerfolgen(p){
 const n=navSnap(p),k=JSON.stringify(n);
 if(NAV_SKIP){NAV_SKIP=false;NAV_CUR={n,k};return;}
 if(NAV_CUR&&NAV_CUR.k===k)return;   // gleiche Seite (z. B. nur neu geladen): nichts merken
 if(NAV_CUR){NAV_STACK.push(NAV_CUR.n);if(NAV_STACK.length>50)NAV_STACK.shift();}
 NAV_CUR={n,k};
}
function navZurueck(){
 const v=NAV_STACK.pop();
 if(!v){go("news");return;}
 NAV_SKIP=true;
 activeBoardId=v.a;activeFach=v.b;activePhaseDetail=v.c;activePPModul=v.d;activeWhiteboardId=v.e;activeWordcloudId=v.f;activeKanbanId=v.g;activeTermPollId=v.h;activeChecklistId=v.i;activeAmpelId=v.j;activePollId=v.k;activeZuordnungId=v.l;activeDeckId=v.m;activeEssayCaseId=v.n;activeConversationUid=v.o;activeConversationName=v.q;activeKwThema=v.r;activeKwLb=v.t;
 if(location.hash!=="#"+v.p)location.hash=v.p;else render();
}
window.navZurueck=navZurueck;
function navZurueckLeiste(content,p,html){
 if(p==="start"||p==="news"||p==="whiteboard-board")return;   // Startseite: nichts zurück; Board-Ansicht hat eigenen Zurück-Knopf
 if(/<button[^>]*>\s*(?:\u2190|&larr;)/.test(String(html||"").slice(0,3500)))return;   // Seite hat schon einen eigenen Zurück-Knopf
 if(!document.getElementById("navBackCss")){const st=document.createElement("style");st.id="navBackCss";st.textContent=".nav-back-bar{margin:0 0 12px}.nav-back{font-size:13px;padding:6px 14px;border-radius:999px}";document.head.appendChild(st);}
 const hatVerlauf=NAV_STACK.length>0;
 const bar=document.createElement("div");bar.className="nav-back-bar";
 bar.innerHTML=`<button type="button" class="secondary nav-back" onclick="${hatVerlauf?"navZurueck()":"go('news')"}">\u2190 ${hatVerlauf?"Zurück":"Startseite"}</button>`;
 content.insertBefore(bar,content.firstChild);
}
async function render(){
 if(!currentUser)return;
 if(typeof wbStop==="function")wbStop();
 if(liveUnsubscribe){liveUnsubscribe();liveUnsubscribe=null;}
 if(liveUnsubHeimat){liveUnsubHeimat();liveUnsubHeimat=null;}
 if(liveUnsubMiniKalender){liveUnsubMiniKalender();liveUnsubMiniKalender=null;}
 const seq=++__campusRenderSeq;
 const p=location.hash.replace("#","")||"news";
 navVerfolgen(p);lxRouteHook(p);
 if(["fach","faecher","start","lernstaende","kw-thema","kw-projekt","kw-checkouts","kw-fortschritt","unterricht-pp"].includes(p)&&typeof ppmLaden==="function")await ppmLaden().catch(()=>{});
 const pages={
 start:renderKachelwand,news:renderStart,"kw-thema":renderKwThema,"kw-projekt":renderKwProjekt,"kw-checkouts":renderKwCheckouts,lernstaende:renderKwCheckouts,"kw-fortschritt":renderKwFortschritt,klassenteam:renderKlassenteam,kompass:renderKompass,lernwerkstatt:renderLernwerkstatt,"ki-lernen":renderKILernen,
 faecher:renderUnterrichtPP,fach:renderUnterrichtPP,"unterricht-pp":renderUnterrichtPP,leistungsnachweis:renderKwCheckouts,didaktik:renderDidaktikKompass,
 ressourcen:renderRessourcenRoute,lernpfad:renderLernpfadRoute,forum:renderForum,"forum-board":renderForumBoard,"forum-nachrichten":renderForumMessages,
 pinnwand:renderPinnwandUebersicht,"pinnwand-board":renderPinnwandBoard,
 kollaboration:renderKollaborationsTools,
 whiteboard:renderWhiteboardUebersicht,tafel:renderTafelUebersicht,"whiteboard-board":renderWhiteboardBoard,
 wortwolke:renderWortwolkeUebersicht,"wortwolke-board":renderWortwolkeBoard,
 kanban:renderKanbanUebersicht,"kanban-board":renderKanbanBoard,
 terminfindung:renderTerminfindungUebersicht,"terminfindung-board":renderTerminfindungBoard,
 teamgesucht:renderTeamgesuchtUebersicht,
 checkliste:renderChecklisteUebersicht,"checkliste-board":renderChecklisteBoard,
 ampel:renderAmpelUebersicht,"ampel-board":renderAmpelBoard,
 umfrage:renderUmfrageUebersicht,"umfrage-board":renderUmfrageBoard,
 zufallspicker:renderZufallspicker,
 lernwerkzeuge:renderLernWerkzeuge,
 zuordnung:renderZuordnungUebersicht,"zuordnung-board":renderZuordnungBoard,
 karteikarten:renderKarteikartenUebersicht,"karteikarten-board":renderKarteikartenBoard,"fokus-timer":renderFokusTimer,"uhr-timer":renderUhrTimer,"qr-code":renderQrCode,
 glossar:renderGlossar,
 fachaufsatz:renderFachaufsatzUebersicht,"fachaufsatz-board":renderFachaufsatzBoard,
 projekte:renderProjekte,kompetenz:renderKompetenz,journal:renderLernjournalRoute,
 praktikum:renderKachelwand,resilienz:renderResilienz,praxisfragen:renderKachelwand,fragenhilfe:renderFragenHilfe,
 praxisprojekte:renderKachelwand,ki:renderKI,kalender:renderKalender,team:renderTeam,
 impulse:renderLernimpulse,lernstand:renderLernstaendeLx,
 kompetenzprofil:()=>modulePlaceholder("Kompetenzprofil"),methoden:renderLernmethoden,lernstrategien:renderLernstrategienTest,metakognition:renderMetakognition,
 lerncoaching:renderLerncoaching
 };
 Object.assign(pages,lxRouten());
 if(p!=="whiteboard-board")wbVonKw=false;
 const fn=pages[p]||renderKachelwand;
 document.querySelectorAll(".nav-link").forEach(a=>a.classList.toggle("active",
 a.dataset.page===p || (a.dataset.page==="forum" && p.startsWith("forum-")) || lxNavAktiv(a.dataset.page,p)));
 document.querySelectorAll('.nav-link[data-page="lernstaende"]').forEach(a=>{if(["lernstaende","kw-checkouts"].includes(p)){const sch=!!a.closest(".nav-area-s");a.classList.toggle("active",isTeacher()?(window.__lsBereich==="s")===sch:sch)}});
 document.querySelectorAll(".nav-mehr").forEach(d=>{d.open=false});
 const content=$("content");
 if(!content)return;
 // Never leave a blank page while a module is loading.
 content.innerHTML=`<div class="card"style="margin:4px 0"><strong>Campus wird geladen …</strong><p style="margin:8px 0 0">Bitte einen Moment.</p></div>`;
 try{
 const html=await Promise.race([
 Promise.resolve().then(()=>fn()),
 new Promise((_,reject)=>setTimeout(()=>reject(new Error("Die Seite hat zu lange zum Laden gebraucht.")),10000))
 ]);
 if(seq!==__campusRenderSeq)return;
 content.innerHTML=html||`<div class="card"><h3>Keine Inhalte vorhanden.</h3></div>`;
 navZurueckLeiste(content,p,html);
 window.scrollTo(0,0);
 if(p==="kompetenz"){
 $("competencySearch")?.addEventListener("input",filterCompetencyNetwork);
 $("competencyCategory")?.addEventListener("change",filterCompetencyNetwork);
 $("competencyHelpersOnly")?.addEventListener("change",filterCompetencyNetwork);
 }
 if(p==="forum-board"){
 $("forumSearch")?.addEventListener("input",filterForumPosts);
 }
 if(p==="klassenteam"){
 subscribeHeimatkarteLive();
 }
 if(p==="start"){
 subscribeMiniKalenderLive();
 }
 if(p==="ampel-board"&&activeAmpelId){
 subscribeAmpelLive(activeAmpelId);
 }
 if(p==="wortwolke-board"&&activeWordcloudId){
 subscribeWordcloudLive(activeWordcloudId);
 }
 if(p==="pinnwand-board"&&activeBoardId){
 subscribePinnwandLive(activeBoardId);
 }
 if(p==="whiteboard-board"&&activeWhiteboardId){
 initWhiteboardBoard(activeWhiteboardId);
 }
 if(typeof window.__ppmNachRender==="function"){const nr=window.__ppmNachRender;window.__ppmNachRender=null;try{nr();}catch(e){console.error("Nachrender:",e);}}
 if(p==="kanban-board"&&activeKanbanId){
 subscribeKanbanLive(activeKanbanId);
 }
 if(p==="checkliste-board"&&activeChecklistId){
 subscribeChecklistLive(activeChecklistId);
 }
 if(p==="umfrage-board"&&activePollId){
 getDoc(doc(db,"polls",activePollId)).then(snap=>{
 if(snap.exists())subscribePollLive(activePollId,snap.data().options||[]);
 });
 }
 if(p==="terminfindung-board"&&activeTermPollId){
 getDoc(doc(db,"termPolls",activeTermPollId)).then(snap=>{
 if(snap.exists())subscribeTerminfindungLive(activeTermPollId,snap.data().slots||[]);
 });
 }
 if(p==="zuordnung-board"){
 initZuordnungDragDrop();
 }
 if(p==="methoden"){
 renderProkChips();
 }
 if(p==="lernstrategien"){
 listAnswers={};
 renderListItems();
 }
 if(p==="metakognition"){
 metaAnswers={};metaOpenPhase=null;metaScenarioAnswers={};
 renderMetaPhases();
 renderMetaScenarios();
 }
 if(p==="fokus-timer"){
 initPomodoroTimer();
 pomodoroUpdateDisplay();
 }
 if(p==="glossar"){
 $("glossarySearch")?.addEventListener("input",filterGlossary);
 }
 }catch(e){
 if(seq!==__campusRenderSeq)return;
 console.error("Campus-Seitenfehler:",e);
 content.innerHTML=`<div class="card"><h3>Die Seite konnte nicht geladen werden.</h3><p>${esc(e?.message||"Unbekannter Fehler")}</p><button class="primary"onclick="go('start')">← Zur Startseite</button></div>`;
 window.scrollTo(0,0);
 }
 updateTeacherTeamNav();
 $("sidebar")?.classList.remove("open");
}

