const LXT={ub:null,fa:null};
async function lxTitelLaden(){
 if(LXT.ub&&LXT.fa)return;
 const[kat,fa]=await Promise.all([kwUbKatalog().catch(()=>[]),faLaden().catch(()=>[])]);
 LXT.ub={};(kat||[]).forEach(k=>{LXT.ub[k.id]=k.titel});LXT.fa={};(fa||[]).forEach(u=>{LXT.fa[u.id]=u.titel});
}
function lxUbTitel(sid){return(LXT.ub&&LXT.ub[sid])||sid}

/* ---------- Lernstands-Kennzahlen je Person und Thema ----------
 D = {ci:[Check-in-Versuche], ub:[Übungsergebnisse], fa:[Fachaufsatz-Selbsteinschätzungen], fort:{uid:{themaId:Dokument}}} */
function lxMetrik(uid,themaId,D){
 const c=D.ci.find(x=>x.uid===uid&&x.wocheId===themaId)||null;
 const v=c?ciVerlauf(c):[];
 const ceD=D.ci.find(x=>x.uid===uid&&x.wocheId===themaId+"@ende"),ceV=ceD?ciVerlauf(ceD):[];
 const wcErst=v.length?v[0].r/v[0].g:null,wcLetzt=ceV.length?ceV[ceV.length-1].r/ceV[ceV.length-1].g:(v.length?v[v.length-1].r/v[v.length-1].g:null);
 const st={};
 D.ub.filter(x=>x.uid===uid&&x.wocheId===themaId&&x.max>0).sort((a,b)=>lxMs(a)-lxMs(b)).forEach(x=>{(st[x.stationId]=st[x.stationId]||[]).push(x)});
 const listen=Object.values(st);
 const ubErst=lxMittel(listen.map(l=>l[0].punkte/l[0].max)),ubLetzt=lxMittel(listen.map(l=>{const z=l[l.length-1];return z.punkte/z.max}));
 const fas=D.fa.filter(x=>x.uid===uid&&x.wocheId===themaId&&x.max>0);
 const faQ=lxMittel(fas.map(x=>x.punkte/x.max));
 const f=((D.fort||{})[uid]||{})[themaId]||{};
 const selbst=Number(f.selbst)||0;
 const teile=[];
 if(wcLetzt!=null)teile.push([wcLetzt,2]);
 if(ubLetzt!=null)teile.push([ubLetzt,1.5]);
 if(faQ!=null)teile.push([faQ,0.75]);
 if(selbst)teile.push([(selbst-1)/3,0.5]);
 const sw=teile.reduce((s,t)=>s+t[1],0),q=sw?teile.reduce((s,t)=>s+t[0]*t[1],0)/sw:null;
 return{c,ende:!!ceD,wcErst,wcLetzt,wcAnz:v.length,ubN:listen.length,ubErst,ubLetzt,faN:fas.length,faQ,selbst,q,ampel:lxAmpel(q),messungen:teile.length-(selbst?1:0),erledigt:!!f.abgeschlossen};
}
// Konkrete Übungs-Hinweise für ein Thema (Schüler:innen)
function lxHinweise(m){
 const h=[];
 if(!m.c)h.push("Mach den Check-in, damit du siehst, wo du stehst.");
 else if(m.wcLetzt<0.75)h.push(`Check-in: ${lxProz(m.wcLetzt)} richtig. Übe mit den Übungs- und Vertiefungsaufgaben (Teil 3) und mach den Check-in danach noch einmal.`);
 if(m.ubErst!=null&&m.ubErst<0.6)h.push(`Beim ersten Versuch hast du bei den Übungen im Schnitt ${lxProz(m.ubErst)} richtig. Wiederhole die Übungen.`);
 if(m.faQ!=null&&m.faQ<0.6)h.push(`Fachaufsatz-Training: Selbsteinschätzung nur ${lxProz(m.faQ)}. Übe noch einen Fachaufsatz zu diesem Thema.`);
 if(m.selbst&&m.selbst<=2)h.push("Du fühlst dich noch unsicher. Lies den Lehrtext (Teil 2) und sieh dir die Tafelbilder (Teil 5) an.");
 if(m.selbst>=3&&m.wcLetzt!=null&&m.wcLetzt<0.5)h.push("Du schätzt dich sicherer ein, als dein Ergebnis zeigt. Schau dir die Fehler im Check-in noch einmal an.");
 if(!m.selbst&&m.c)h.push("Schätze dich noch selbst ein (Teil 7), das hilft dir beim Planen.");
 return h;
}
// Alle für die Person sichtbaren Themen mit Kennzahlen, sortiert nach Übungsbedarf
function lxMeineThemen(L){
 const D={ci:Object.values(L.ci),ub:L.ub,fa:L.fa,fort:{[currentUser.uid]:KW.fort||{}}};
 const uid=currentUser.uid,out=[];
 LX_CFG.phasen().slice().sort((a,b)=>a.lbNum-b.lbNum).forEach(ph=>kwThemenVonPhase(ph).forEach(e=>{
  if(!lxThemaSichtbar(e))return;
  const m=lxMetrik(uid,e.id,D);out.push({e,ph,m,hin:lxHinweise(m)});
 }));
 return out;
}

/* ---------- Unterrichtsfächer ---------- */
function lxKachel(href,titel,text,opt){
 opt=opt||{};
 const inner=`<b>${esc(titel)}</b>${text?`<small>${text}</small>`:""}${opt.extra||""}`;
 return opt.aus?`<div class="lx-kachel lx-aus" aria-disabled="true">${inner}</div>`
  :opt.data?`<button type="button" class="lx-kachel" ${opt.data}>${inner}</button>`
  :`<a class="lx-kachel" href="#${esc(href)}">${inner}</a>`;
}

async function renderUnterrichtsfaecher(){

 const L=[["Deutsch", ""], ["Englisch", ""], ["Mathematik", ""], ["Religion / Ethik", ""], ["Politik und Gesellschaft", ""], ["SWR", ""], ["Biologie", ""], ["Soziologie", ""], ["Wahlpflicht 1", ""], ["Wahlpflicht 2", ""]];
 const kachel=(t,badge,txt,href)=>`<${href?'button type="button" onclick="lxPPDirekt()"':'div'} class="lxf-k${href?" an":""}"><h3>${esc(t)}</h3><span class="lxf-b${href?" muster":""}">${esc(badge)}</span><p>${esc(txt)}</p></${href?"button":"div"}>`;
 return`${kwSchuelerBanner()}<div class="lxf"><small class="lxf-kick">LERNPFADE</small><h1>Meine Lernpfade in der 12. Klasse</h1><p class="lxf-sub">Wähle ein Fach. Du kommst direkt zum Thema, an dem du gerade arbeitest. Pädagogik / Psychologie ist das Muster, die anderen Fächer werden nach demselben Aufbau ausgearbeitet.</p>
 <div class="lxf-grid">${kachel("Pädagogik / Psychologie","Ausgearbeitet als Muster","4 Lernbereiche, Meine Lernpfade, Lernweg mit Check-in und Check-out",true)}${L.map(x=>kachel(x[0],x[1]&&x[1].startsWith("Nicht")?x[1]:"Folgt",x[1]&&!x[1].startsWith("Nicht")?x[1]:"Lernpfad, Themen und Material kommen aus deinen Unterlagen.")).join("")}</div></div>${footer()}`;
}
async function renderUnterrichtsfaecherAlt(){
 await kwLaden().catch(()=>{});
 const lehrer=kwLehrer();
 const alle=LX_CFG.phasen().flatMap(kwThemenSicht);
 const fertig=lehrer?alle.filter(e=>(KW.mat[e.id]||[]).length||kwModuleThema(e.id).length).length:alle.filter(e=>kwErledigt(e.id)).length;
 const p=alle.length?Math.round(fertig/alle.length*100):0;
 const bar=`<span class="lx-bar" role="progressbar" aria-valuenow="${p}" aria-valuemin="0" aria-valuemax="100"><i style="width:${p}%"></i></span><span class="lx-bar-t">${lehrer?"Vorbereitet":"Erledigt"}: ${p} %</span>`;
 return`${kwSchuelerBanner()}${pageHead("LERNLANDKARTE","Fächer der 12. Klasse","Wähle ein Fach. Dort findest du alle Themen mit dem Lernweg: Check-in, Infotext, Selbstlernkurs, Üben, Check-out.")}
 <div class="lx-kacheln lx-faecher">
  ${lxKachel("start","Pädagogik / Psychologie","Lernpfad mit 4 Lernbereichen und 29 Themen. Lernweg mit Check-in und Check-out.",{extra:bar})}
  ${["Deutsch","Englisch","Mathematik","Religionslehre / Ethik","Politik und Gesellschaft","Sozialwirtschaft und Recht","Biologie","Soziologie","Wahlpflichtfach 1","Wahlpflichtfach 2"].map(n=>lxKachel("",n,"Lernpfad und Material folgen",{aus:true,extra:'<span class="lx-badge">folgt</span>'})).join("")}
 </div>${footer()}`;
}

/* ---------- Meine Lernpfade (Kachelwand) ---------- */
function lxLandkartenKacheln(lehrer){
 return`<div class="lx-kacheln">
  ${lehrer?"":lxKachel("lernstaende","Meine Lernstände","Nur dein eigener Stand: Wo stehst du, was solltest du noch üben?")}
  ${lxKachel("journal",lehrer?"Lernjournal":"Mein Lernjournal","Gedanken zum Lernen festhalten")}
  ${lxKachel("ressourcen","Lernressourcen","Links, Videos, KI-Angebote und Material")}
 </div>`;
}
// Schüler:innen sehen nur Themen, zu denen die Lehrkraft Material oder Bausteine eingestellt hat
function kwHatMaterial(e){return !!e&&((KW.mat[e.id]||[]).length>0||kwModuleThema(e.id).length>0)}
function kwThemenSicht(ph){const t=kwThemenVonPhase(ph);return kwLehrer()?t:t.filter(kwHatMaterial)}
// Teile-Punkte (Check-in, Infotext, Selbstlernkurs, Üben, Check-out) und „Schüler ab“-Datum je Thema (Lehrkraft-Ansicht der Kachelwand)
function lxThemaPunkte(e,ph){
 const mats=KW.mat[e.id]||[],mod=kwModuleThema(e.id);
 const has=k=>mats.some(m=>m.kategorie===k||(k==="vertiefung"&&/^vertiefung/.test(m.kategorie||"")));
 const teile=[
  [1,has("checkin")||checkinAusBank(e.id).length>0],[2,has("einfuehrung")||has("lernsituation")||has("lehrtext")||has("arbeitsblatt")||has("audio")||has("video")||has("tafel")||has("lernuebersicht")],
  [4,mod.some(m=>m.modul!=="fachaufsatz"&&m.modul!=="apt")],[3,has("uebung")||has("vertiefung")||mod.some(m=>m.modul==="fachaufsatz"||m.modul==="apt")],[6,checkinAusBank(e.id+"@ende").length>0]];
 const pts=teile.map(([n,ok])=>`<i class="lx-pt${ok?" an":""}" style="--k:${LXD[n]||LXF[n].c}" title="${esc(LXF[n].n)}: ${ok?"vorhanden":"fehlt"}"></i>`).join("");
 const st=lxThemaStart(e);
 return`<small class="lx-pts" aria-label="Vorhandene Teile">${pts}</small>${st?`<small class="lx-ab">Sch\u00FCler ab ${esc(fmtKurz(st))}</small>`:""}`;
}
function kwKachelHTML(ph,lehrer){
 const F=kwFarbe(ph.lbNum),themen=kwThemenSicht(ph),heute=lxHeute();
 const n=themen.length;
 const fertig=lehrer?themen.filter(e=>(KW.mat[e.id]||[]).length||kwModuleThema(e.id).length).length:themen.filter(e=>kwErledigt(e.id)).length;
 const proz=n?Math.round(fertig/n*100):0;
 const status=lehrer?"":(fertig===n&&n?"geschafft":(ph.start<=heute&&ph.end>=heute?"läuft gerade":(ph.start>heute?(proz?"begonnen":"folgt"):"offen")));
 const naechst=!lehrer&&LX_CFG.phasen().filter(p=>p.end>=heute).sort((a,b)=>a.start.localeCompare(b.start))[0]===ph&&ph.start>heute;
 const projM=PPM.liste.find(m=>m.modul==="projekt"&&Number(m.lb)===ph.lbNum&&!m.projektId);
 const projTitel=(projM&&projM.titel)||ph.titel;
 const z={};kwModuleLb(ph.lbNum).forEach(m=>{z[m.modul]=(z[m.modul]||0)+1});
 const nCo=KW.co&&KW.co.checkouts?KW.co.checkouts.filter(c=>Number(c.lbNum)===ph.lbNum).length:0;
 if(nCo&&!z.kprim)z.kprim=nCo;
 const chips=Object.entries(z).map(([k,v])=>{const b=KW_BAUSTEINE[k];return b?`<span class="chip ${b[1]}">${v} ${esc(b[0])}</span>`:""}).join("")||`<span class="kw-leer">Noch keine Bausteine vorbereitet</span>`;
 const rows=themen.map(e=>{
  if(!lehrer&&!lxThemaSichtbar(e))return lxGesperrtRow(e);
  const ok=!lehrer&&kwErledigt(e.id),nm=(KW.mat[e.id]||[]).length+kwModuleThema(e.id).length;
  const ab=lehrer?lxThemaPunkte(e,ph):"";
  return`<button type="button" class="kw-row" data-kw="thema" data-id="${esc(e.id)}"><i class="kw-bx${ok?" d":""}"></i><em>${esc(e.nr)}</em><span>${esc(kwKurz(e))}</span>${ab}${nm?`<small>${nm}</small>`:""}</button>`;
 }).join("");
 const projStart=LX_CFG.projektStart(ph);
 const projSichtbar=lehrer||lxPhaseSichtbar(ph);
 const projKnopf=projSichtbar
  ?`<button type="button" class="kw-proj" data-kw="projekt" data-lb="${ph.lbNum}"><span class="chip prj">Projekt</span><b>${esc(projTitel)}</b><small>${fmtKurz(ph.projektStart)}–${fmtKurz(ph.projektEnde)}</small></button>`
  :`<div class="kw-proj lx-lock"><span class="chip prj">Projekt</span><b>${esc(projTitel)}</b><small class="lx-ab">folgt</small></div>`;
 return`<article class="kw-tile${naechst?" kw-next":""}" style="--c:${F.c};--bg:${F.bg};--t:${F.t}">
  <header class="kw-th"><div><small>LB ${ph.lbNum} · ${esc(kwBlockText(ph.start,ph.end)||fmtKurz(ph.start))}</small><b>${esc(ph.lbTitel)}</b></div>${lxLbProjekte(ph.lbNum)}${status?`<span class="kw-st">${naechst?"als Nächstes":status}</span>`:""}</header>
  ${projKnopf}
  <div class="kw-lab">${n} THEMEN · ${lehrer?fertig+" MIT MATERIAL":fertig+" ERLEDIGT"}</div>
  <div class="kw-rows">${rows||(lehrer?"":`<div class="kw-leer">Hier ist noch nichts eingestellt.</div>`)}${kwLeistungRow(ph)}</div>
  <div class="kw-lab">BAUSTEINE DER LEHRKRÄFTE</div>
  <div class="kw-chips">${chips}</div>
  <footer class="kw-fuss"><div class="kw-bar" role="progressbar" aria-valuenow="${proz}" aria-valuemin="0" aria-valuemax="100" aria-label="${lehrer?"Vorbereitung":"Fortschritt"} Lernbereich ${ph.lbNum}"><i style="width:${proz}%"></i></div><span>${lehrer?"Vorbereitet":"Fortschritt"} ${proz} %</span></footer>
 </article>`;
}

/* ---------- Neue Meine Lernpfade (Entwurf) ---------- */
function lxLandkarteNeu(){
 const heute=lxHeute(),FACH=["Pädagogik / Psychologie", "Deutsch", "Englisch", "Mathematik", "Religion / Ethik", "Politik und Gesellschaft", "Sport", "SWR", "Biologie", "Soziologie", "Wahlpflicht 1", "Wahlpflicht 2"];
 const phasen=[...LX_CFG.phasen()].sort((a,b)=>a.lbNum-b.lbNum);
 const akt=phasen.find(p=>p.start<=heute&&heute<=p.end)||phasen.find(p=>p.start>heute)||phasen[phasen.length-1];
 const spalte=ph=>{
  const th=kwThemenSicht(ph).filter(e=>e.typ!=="projekt"),pr=PP_EINHEITEN_PROJEKT(ph),cur=ph===akt;
  const rows=th.map(e=>{const f=KW.fort[e.id]||{},z=f.abgeschlossen?"f":(f.info?"h":"");return`<button type="button" class="lxl-th" data-kw="thema" data-id="${esc(e.id)}" title="${z==="f"?"geschafft":(z==="h"?"begonnen":"noch offen")}"><em>${esc(e.nr)}</em><span>${esc(kwKurz(e))}${(LXWA.d||[]).some(w=>(w.themen||[]).includes(e.id)&&(w.bis||"")>=heute)?`<b class="lxl-wa">Diese Woche</b>`:""}</span><span class="lxl-pk"><i class="${z} t"></i></span></button>`}).join("");
  return`<section class="lxl-lb"><header class="lxl-kopf"><small>LB ${ph.lbNum}</small>${cur?`<span class="lxl-akt">AKTUELL</span>`:""}<h3>${esc(ph.lbTitel||"")}</h3><span class="lxl-n">${th.length} Themen</span>${pr}</header><div class="lxl-liste">${rows||`<div class="kw-leer">Noch keine Themen freigeschaltet.</div>`}</div></section>`;
 };
 const first=kwThemenSicht(akt).find(e=>e.typ!=="projekt");
 return`${kwSchuelerBanner()}<div class="lxl"><div class="lxl-tabs">${FACH.map((f,i)=>`<button type="button" class="lxl-tab${i?"":" an"}" data-lxf="${i}">${esc(f)}</button>`).join("")}</div><h1>Meine Lernpfade</h1><p class="lxl-h">Deine Bibliothek: Alle Themen mit Infotext, Übungen und Check-out. Du entscheidest, womit du anfängst. Der Punkt zeigt: offen, begonnen oder geschafft.</p>
 <div class="lxl-spalten">${phasen.map(spalte).join("")}</div><div class="lxl-folgt kw-leer" hidden>Dieses Fach folgt. Themen und Material kommen aus deinen Unterlagen.</div></div>${footer()}`;
}
function PP_EINHEITEN_PROJEKT(ph){
 const t=String((ph.titel||"")).trim(),a=ph.projektStart||ph.start,b=ph.projektEnde||ph.end;
 if(!t)return"";
 return`<div class="lxl-pr"><span>Projekt</span><b>${esc(t)}</b><small>${esc(fmtKurz(a))}–${esc(fmtKurz(b))}</small></div>`;
}
document.addEventListener("click",ev=>{const b=ev.target.closest&&ev.target.closest(".lxl-tab");if(!b)return;const w=b.closest(".lxl");if(!w)return;w.querySelectorAll(".lxl-tab").forEach(x=>x.classList.toggle("an",x===b));const first=b.dataset.lxf==="0";const sp=w.querySelector(".lxl-spalten"),fo=w.querySelector(".lxl-folgt");if(sp)sp.hidden=!first;if(fo)fo.hidden=first});
function lxlAuswahl(e){
 if(!e)return"";
 const m=(KW.mat[e.id]||[]),dl=k=>{const x=m.find(y=>y.kategorie===k);return x&&x.url?`<a class="secondary lxl-dl" href="${esc(x.url)}" target="_blank" rel="noopener">${k==="lehrtext"?"Infotext (PDF)":"Zusammenfassung (PDF)"}</a>`:""};
 return`<div><small>AUSGEWÄHLT</small><h2>${esc(kwKurz(e))}</h2><p>Lehrtexte zum Thema</p></div><div class="lxl-sa">${dl("lehrtext")}${dl("lernuebersicht")}<button type="button" class="primary" data-kw="thema" data-id="${esc(e.id)}">Thema öffnen</button></div>`;
}
document.addEventListener("click",ev=>{const b=ev.target.closest&&ev.target.closest("[data-lxl]");if(!b)return;const e=LX_CFG.phasen().flatMap(kwThemenVonPhase).find(x=>x.id===b.dataset.lxl);document.querySelectorAll(".lxl-th.an").forEach(x=>x.classList.remove("an"));b.classList.add("an");const w=document.getElementById("lxlSel");if(w&&e)w.innerHTML=lxlAuswahl(e)});

async function renderKachelwand(){
 try{await ppmLaden()}catch(e){}
 await kwLaden();
 const lehrer=kwLehrer();
 if(!lehrer){await lxWaLaden().catch(()=>{});return lxLandkarteNeu()}
 const alle=LX_CFG.phasen().flatMap(kwThemenSicht);
 const fertig=lehrer?alle.filter(e=>(KW.mat[e.id]||[]).length||kwModuleThema(e.id).length).length:alle.filter(e=>kwErledigt(e.id)).length;
 const p=alle.length?Math.round(fertig/alle.length*100):0;
 const r=31,u=2*Math.PI*r,da=(u*p/100).toFixed(1);
 const ring=`<svg width="56" height="56" viewBox="0 0 78 78" role="img" aria-label="Gesamtstand ${p} Prozent"><circle cx="39" cy="39" r="${r}" fill="none" stroke="#DCE9F5" stroke-width="10"/><circle cx="39" cy="39" r="${r}" fill="none" stroke="#3A8FD4" stroke-width="10" stroke-dasharray="${da} ${u.toFixed(1)}" transform="rotate(-90 39 39)" stroke-linecap="round"/></svg>`;
 const lk=lehrer?`<div class="kw-links"><button class="secondary" onclick="kwSchuelerUmschalten(true)">Schüleransicht</button></div>`:"";
 return`<div class="kw" id="kwRoot">
  ${kwSchuelerBanner()}
  <button class="secondary" onclick="go('unterricht')">← Unterrichtsfächer</button>
  ${lehrer?pageHead("LEHRKRÄFTE · PÄDAGOGIK/PSYCHOLOGIE","Unterrichtsbibliothek","Hier füllst du alle Materialien in die vier Lernbereiche ein. Eine Ebene tiefer, beim Klick auf ein Thema, stellst du die Materialien für die Schüler:innen bereit und wählst aus, was in ihrem Lernpfad erscheint."):pageHead("PÄDAGOGIK/PSYCHOLOGIE","Meine Lernpfade","Dein Weg durch das Schuljahr: vier Lernbereiche mit Projekt, Themen und Bausteinen.")}
  <div class="kw-top">${kwHeroHTML()}<div class="kw-gesamt">${ring}<div><b>${lehrer?"Vorbereitung":"Gesamtstand"} ${p} %</b><small>${fertig} von ${alle.length} Themen ${lehrer?"mit Material oder Baustein":"erledigt"}</small></div></div></div>
  ${lehrer?"":lxLandkartenKacheln(lehrer)}
  ${lk}
  ${lehrer?`<p class="lx-hint">Ein Klick auf ein Thema öffnet die Bearbeitungsseite dieses Themas mit Check-in, Infotext, Üben und Vertiefen und Check-out. Die Punkte zeigen, was schon gefüllt ist. Schüler:innen sehen ein Thema ab dem Datum „Schüler ab …“; Projekte legst und bearbeitest du im Kopf des Lernbereichs.</p>${lxLegende()}`:""}
  <div class="kw-wand${lehrer?" lx-wahl":""}">${[...LX_CFG.phasen()].sort((a,b)=>a.lbNum-b.lbNum).map(ph=>kwKachelHTML(ph,lehrer)).join("")}</div>
  ${lehrer?lxWerkzeuge():""}
 </div>${footer()}`;
}

/* ---------- Themenseite: immer dieselben acht Teile in derselben Reihenfolge ---------- */
function lxSek(nr,titel,hint,inner,extra){
 const F=LXF[nr];
 return`<section class="lx-sek" id="lx-s${nr}" style="--k:${F.c};--kb:${F.bg}"><header class="lx-sek-k"><span class="lx-nr">${F.d||nr}</span><div><h3>${esc(titel)}</h3>${hint?`<small>${esc(hint)}</small>`:""}</div></header>${extra||""}${inner}</section>`;
}
function lxCoZeile(c,d,lehrer){
 const a=(d.meineAbgaben||{})[c.id];
 const st=c.status==="live"?`<span class="co-chip live"><span class="co-live-punkt"></span>läuft</span>`:c.status==="beendet"?`<span class="co-chip fertig">beendet</span>`:`<span class="co-chip entwurf">Entwurf</span>`;
 let info,rechts;
 if(lehrer){
  info=c.status==="live"?"läuft jetzt":(c.status==="beendet"?"beendet":"Entwurf");
  rechts=c.status==="entwurf"?`<button class="secondary" data-lx="co" data-op="edit" data-id="${c.id}">Bearbeiten</button><button class="primary" data-lx="co" data-op="live" data-id="${c.id}">▶ Live freischalten</button>`
   :c.status==="live"?`<button class="primary" data-lx="co" data-op="monitor" data-id="${c.id}">Live-Übersicht</button>`
   :`<button class="secondary" data-lx="co" data-op="erg" data-id="${c.id}">Ergebnisse</button>`;
 }else{
  info=a&&a.ausgewertet?npText(a.notenpunkte):(a&&a.abgegeben?"abgegeben, wird ausgewertet":(c.status==="live"?"läuft jetzt":"nicht teilgenommen"));
  rechts=c.status==="live"?(a&&a.abgegeben?`<span class="co-chip fertig">abgegeben ✓</span>`:`<button class="primary" data-lx="co" data-op="test" data-id="${c.id}">${a?"Weiter":"Starten"}</button>`)
   :(a&&a.ausgewertet?`<button class="secondary" data-lx="co" data-op="mein" data-id="${c.id}">Ansehen</button>`:"");
 }
 return`<div class="ls-zeile"><div class="ls-t"><b>${esc(coTitelAnzeige(c)||"Check-out")}</b><small>${coDatum(c.datum)} · ${(c.aufgaben||[]).length} K-Prim-Aufgaben · ${esc(info)}</small></div>${st}<div class="ls-a">${rechts}</div></div>`;
}
const LX_SELBST=[[1,"Noch unsicher"],[2,"Ein bisschen"],[3,"Ziemlich sicher"],[4,"Sicher"]];
function lxSelbstHTML(themaId,aktuell){
 return`<div class="lx-selbst" role="group" aria-label="Selbsteinschätzung"><b>Wie sicher fühlst du dich bei diesem Thema?</b><div>${LX_SELBST.map(([w,t])=>`<button type="button" class="lx-sb${aktuell===w?" an":""}" data-lx="selbst" data-id="${esc(themaId)}" data-w="${w}">${esc(t)}</button>`).join("")}</div></div>`;
}
async function lxLernstandThemaSchueler(e,ph){
 await lxTitelLaden().catch(()=>{});
 const L=await lxMeinLaden();
 const D={ci:Object.values(L.ci),ub:L.ub,fa:L.fa,fort:{[currentUser.uid]:KW.fort||{}}};
 const m=lxMetrik(currentUser.uid,e.id,D);
 const zeilen=[];
 zeilen.push(`<div class="lx-ls-z"><span>Check-in</span><b>${m.c?(m.ende?`${lxProz(m.wcErst)} → ${lxProz(m.wcLetzt)}`:(m.wcAnz>1?`${lxProz(m.wcErst)} → ${lxProz(m.wcLetzt)}`:lxProz(m.wcLetzt))):(m.ende?lxProz(m.wcLetzt):"noch nicht gemacht")}</b><small>${m.ende?"Start und Check-out":(m.c?(m.wcAnz>1?`${m.wcAnz} Versuche, Start und aktueller Stand`:"nach dem Üben den Check-out machen"):"")}</small></div>`);
 zeilen.push(`<div class="lx-ls-z"><span>Übungsaufgaben</span><b>${m.ubN?`${lxProz(m.ubErst)} beim 1. Versuch`:"noch keine gemacht"}</b><small>${m.ubN?`${m.ubN} ${m.ubN===1?"Übung":"Übungen"}, zuletzt Ø ${lxProz(m.ubLetzt)}`:""}</small></div>`);
 zeilen.push(`<div class="lx-ls-z"><span>Fachaufsatz-Training</span><b>${m.faN?`Ø ${lxProz(m.faQ)} (Selbsteinschätzung)`:"noch keines gemacht"}</b><small>${m.faN?`${m.faN} ${m.faN===1?"Aufsatz":"Aufsätze"}`:""}</small></div>`);
 const hin=lxHinweise(m);
 const ampel=m.ampel?lxPunkt(m.ampel,LX_AMP[m.ampel][1]):"";
 const box=hin.length?`<div class="lx-ueben"><b>Das solltest du noch üben</b><ul>${hin.map(t=>`<li>${esc(t)}</li>`).join("")}</ul></div>`:`<div class="lx-ueben ok"><b>Dieses Thema sitzt.</b> Mach weiter mit dem nächsten.</div>`;
 return lxSek(7,LXF[7].n,"Wo du stehst und was du noch üben solltest",`<div class="lx-ls">${m.ampel?`<div class="lx-ls-z"><span>Gesamteindruck</span><b>${ampel} ${LX_AMP[m.ampel][1]}</b><small>aus allen Messungen zu diesem Thema</small></div>`:""}${zeilen.join("")}</div>${ceThemaBlockHTML(e,D,currentUser.uid)}${lxSelbstHTML(e.id,m.selbst)}${box}`);
}
async function lxLernstandThemaLehrer(e){
 const K=await lxKlasseLaden();
 const N=K.schueler.length,cs=K.ci.filter(x=>x.wocheId===e.id);
 const mm=K.schueler.map(u=>lxMetrik(u.uid,e.id,K));
 const g=k=>mm.filter(m=>m.ampel===k).length;
 const sel=[1,2,3,4].map(w=>mm.filter(m=>m.selbst===w).length);
 const ub=lxMittel(mm.map(m=>m.ubErst).filter(v=>v!=null));
 const sicher=sel[0]+sel[1];
 return lxSek(7,LXF[7].n,"Wo die Klasse bei diesem Thema steht",
  `<div class="lx-ls">
   <div class="lx-ls-z"><span>Check-in gemacht</span><b>${cs.length} von ${N}</b><small>${lxPunkt("gruen")}${g("gruen")} grün · ${lxPunkt("orange")}${g("orange")} gelb · ${lxPunkt("rot")}${g("rot")} rot</small></div>
   <div class="lx-ls-z"><span>Übungen, 1. Versuch</span><b>${ub==null?"noch keine Ergebnisse":"Ø "+lxProz(ub)}</b></div>
   <div class="lx-ls-z"><span>Selbsteinschätzung</span><b>${sel.reduce((a,b)=>a+b,0)} von ${N}</b><small>unsicher oder ein bisschen: ${sicher}</small></div>
  </div>
  ${(g("rot")+g("orange")>=Math.max(2,Math.ceil(N*0.3))||sicher>=Math.max(2,Math.ceil(N*0.3)))?`<div class="lx-ueben"><b>Hier haben viele noch Schwierigkeiten</b><ul><li>${g("rot")+g("orange")} von ${N} liegen im gelben oder roten Bereich${sicher?`, ${sicher} schätzen sich unsicher ein`:""}. Plane eine Wiederholung oder eine Übungsstunde ein.</li></ul></div>`:""}
  ${ceKlasseThemaHTML(e,K)}
  <div class="kw-aktionen"><button class="secondary" data-ls="thema" data-id="${esc(e.id)}">Wer braucht Hilfe? (Einzelergebnisse)</button><button class="secondary" onclick="go('lernstaende')">Alle Lernstände</button></div>`);
}
/* ===== Neuer Lernpfad (Bibliothek): Check-in → Infotext → Üben und Vertiefen → Check-out ===== */
const LX_PFAD=[["checkin","Check-in","Was weißt du schon?"],["infotext","Infotext","Lesen, Hören oder Sehen"],["ueben","Üben und Vertiefen","Wenn du noch unsicher bist"],["checkout","Check-out","Zeig, was du kannst"]];
window.__lxPfadWahl=window.__lxPfadWahl||{};
const LXW_FAECHER=["Pädagogik / Psychologie","Deutsch","Englisch","Mathematik","Religion / Ethik","Politik und Gesellschaft","Sport","SWR","Biologie","Soziologie","Wahlpflicht 1","Wahlpflicht 2"];
const LXWA={t:0,d:[],pt:[]};
async function lxWaLaden(erzwingen){
 if(!erzwingen&&LXWA.t&&Date.now()-LXWA.t<30000&&LXWA.t>(window.__fsDirty||0))return LXWA.d;
 const hole=async n=>{try{return(await getDocs(collection(db,n))).docs.map(d=>({id:d.id,...d.data()}))}catch(e){return[]}};
 const[a,b]=await Promise.all([hole("wochenauftraege"),hole("pflichttermine")]);
 LXWA.d=a;LXWA.pt=b;LXWA.t=Date.now();return a;
}
