/* ---------- Lernstände: Hinweise ---------- */
function lxCoHinweise(){
 const co=KW.co,out=[];if(!co||!co.checkouts)return out;
 co.checkouts.forEach(c=>{const a=(co.meineAbgaben||{})[c.id];
  if(c.status==="live"&&!(a&&a.abgegeben))out.push({t:`Check-out „${coTitelAnzeige(c)||"Check-out"}“ läuft jetzt. Nimm teil.`,go:"tests"});
  else if(a&&a.ausgewertet&&Number(a.notenpunkte)<8)out.push({t:`Check-out „${coTitelAnzeige(c)||"Check-out"}“: ${a.notenpunkte} Notenpunkte. Wiederhole die Themen von Lernbereich ${c.lbNum}.`,go:"lernstaende"});
 });
 return out;
}
async function lxHinweisBox(){
 await kwLaden();
 if(kwLehrer()){
  const K=await lxKlasseLaden(),N=K.schueler.length;
  const zeilen=[];
  LX_CFG.phasen().slice().sort((a,b)=>a.lbNum-b.lbNum).forEach(ph=>kwThemenVonPhase(ph).forEach(e=>{
   const mm=K.schueler.map(u=>lxMetrik(u.uid,e.id,K));
   const gemessen=mm.filter(m=>m.ampel);if(gemessen.length<2)return;
   const schwer=gemessen.filter(m=>m.ampel!=="gruen").length,anteil=schwer/gemessen.length;
   if(anteil>=0.4&&schwer>=2)zeilen.push({e,schwer,n:gemessen.length,anteil,ub:lxMittel(mm.map(m=>m.ubErst).filter(v=>v!=null)),uns:mm.filter(m=>m.selbst&&m.selbst<=2).length});
  }));
  zeilen.sort((a,b)=>b.anteil-a.anteil||b.schwer-a.schwer);
  if(!zeilen.length)return`<div class="lx-ueben ok"><b>Hinweis für den Unterricht:</b> Im Moment fällt kein Thema auf, bei dem viele Schwierigkeiten haben.</div>`;
  return`<div class="lx-ueben"><b>Hier haben viele noch Schwierigkeiten</b><ul>${zeilen.slice(0,5).map(z=>`<li><button type="button" class="text-button" data-ls="thema" data-id="${esc(z.e.id)}">${esc(lsThemaName(z.e.id))}</button>: ${z.schwer} von ${z.n} im gelben oder roten Bereich${z.ub!=null?`, Übungen beim 1. Versuch Ø ${lxProz(z.ub)}`:""}${z.uns?`, ${z.uns} schätzen sich unsicher ein`:""}. Eine Wiederholung oder Übungsstunde würde helfen.</li>`).join("")}</ul></div>`;
 }
 const L=await lxMeinLaden(true),T=lxMeineThemen(L);
 const lis=lxCoHinweise().map(h=>`<li><button type="button" class="text-button" onclick="go('${h.go}')">${esc(h.t)}</button></li>`);
 T.filter(x=>x.hin.length&&!x.m.erledigt).sort((a,b)=>(a.m.q==null?0.5:a.m.q)-(b.m.q==null?0.5:b.m.q)).slice(0,5)
  .forEach(x=>lis.push(`<li><button type="button" class="text-button" data-kw="thema" data-id="${esc(x.e.id)}">${esc(lsThemaName(x.e.id))}</button>: ${esc(x.hin[0])}</li>`));
 const tab=T.map(x=>`<tr><th scope="row"><button type="button" class="text-button" data-kw="thema" data-id="${esc(x.e.id)}">${esc(lsThemaName(x.e.id))}</button></th><td>${x.m.ampel?lxPunkt(x.m.ampel,LX_AMP[x.m.ampel][1]):"–"}</td><td>${x.m.c?lxProz(x.m.wcLetzt):"–"}</td><td>${x.m.ubN?lxProz(x.m.ubErst):"–"}</td><td>${x.m.faN?lxProz(x.m.faQ):"–"}</td><td>${x.m.selbst?LX_SELBST[x.m.selbst-1][1]:"–"}</td></tr>`).join("");
 return`${lis.length?`<div class="lx-ueben"><b>Das solltest du noch üben</b><ul>${lis.join("")}</ul></div>`:`<div class="lx-ueben ok"><b>Gut gemacht.</b> Im Moment gibt es nichts, was du dringend üben musst.</div>`}
 <details class="kw-card"><summary><b>Mein Stand je Thema</b> <small>Check-in, Übungen (1. Versuch), Fachaufsatz, Selbsteinschätzung</small></summary><div class="kw-tabwrap"><table class="kw-tab"><thead><tr><th>Thema</th><th>Stand</th><th>Check-in</th><th>Übungen</th><th>Aufsatz</th><th>Selbst</th></tr></thead><tbody>${tab}</tbody></table></div></details>`;
}

/* ---------- Neue Lernstände: Check-in, Check-out, Übungen, Tests ---------- */
function lsnBar(q,k){return q==null?`<span class="lsn-leer">–</span>`:`<span class="lsn-bar ${k||""}"><i style="width:${Math.round(q*100)}%"></i></span><b>${Math.round(q*100)} %</b>`}
function lsnZu(a,b){if(a==null||b==null)return`<span class="lsn-leer">–</span>`;const z=Math.round((b-a)*100);return`<b class="lsn-zu ${z>0?"auf":(z<0?"ab":"")}">${z>0?"▲ +":(z<0?"▼ ":"")}${z} %</b>`}
function lsnPz(p){return p?p.r/p.g:null}
function lxLerntipp(rows){
 const nm=r=>esc(lsThemaName(r.e.id)),bt=r=>`<button type="button" class="secondary" data-kw="thema" data-id="${esc(r.e.id)}">Zum Thema</button>`;
 let t="",r0=null;
 const ohneCi=rows.filter(r=>!r.ciN),mitCi=rows.filter(r=>r.ci!=null);
 const schwachCi=mitCi.filter(r=>r.ci<0.5&&!r.m.ubN).sort((a,b)=>a.ci-b.ci)[0];
 const schwachUb=rows.filter(r=>r.m.ubN&&r.m.ubErst!=null&&r.m.ubErst<0.6).sort((a,b)=>a.m.ubErst-b.m.ubErst)[0];
 const schwachCo=rows.filter(r=>r.co!=null&&r.co<0.6).sort((a,b)=>a.co-b.co)[0];
 const unsicher=rows.find(r=>r.m.selbst&&r.m.selbst<=2);
 if(!mitCi.length){t="Starte mit einem Check-in. Er dauert nur wenige Minuten, zählt nicht für die Note und zeigt dir, womit du anfangen solltest.";}
 else if(schwachCo){r0=schwachCo;t=`Im Check-out zu „${nm(schwachCo)}“ hast du ${Math.round(schwachCo.co*100)} % erreicht. Lies den Infotext noch einmal und mach danach zwei bis drei Übungen auf Basis-Niveau. Wiederholen nach ein bis zwei Tagen wirkt besser als alles an einem Abend.`}
 else if(schwachUb){r0=schwachUb;t=`Bei „${nm(schwachUb)}“ lagst du in den Übungen beim ersten Versuch bei ${Math.round(schwachUb.m.ubErst*100)} %. Probiere die Übung nach einer Pause noch einmal. Beim zweiten Versuch steigen die Ergebnisse meist deutlich.`}
 else if(schwachCi){r0=schwachCi;t=`Dein Check-in zu „${nm(schwachCi)}“ lag bei ${Math.round(schwachCi.ci*100)} %. Das ist ein guter Startpunkt: Lies den Infotext und starte dann mit den Basis-Übungen.`}
 else if(unsicher){r0=unsicher;t=`Bei „${nm(unsicher)}“ hast du dich unsicher eingeschätzt. Erkläre das Thema in eigenen Worten, laut oder schriftlich. Wo du stockst, lohnt sich eine Übung.`}
 else if(ohneCi.length){r0=ohneCi[0];t=`Zu „${nm(ohneCi[0])}“ fehlt noch dein Check-in. Mach ihn vor dem Lernen, dann siehst du, wo du schon sicher bist.`}
 else t="Dein Stand sieht gut aus. Wenn du mehr willst, probiere die Übungen in AFB II oder AFB III oder erkläre einer Mitschülerin ein Thema. Erklären festigt am meisten.";
 const allg=["Kurze Lerneinheiten von 20 bis 25 Minuten mit Pause sind wirksamer als ein langer Block.","Teste dich selbst, bevor du nachliest. Abrufen bleibt besser hängen als Wiederlesen.","Wiederhole nach einem Tag, nach drei Tagen und nach einer Woche. Diese Abstände helfen dem Gedächtnis.","Verbinde neue Begriffe mit einem eigenen Beispiel aus dem Alltag oder dem Praktikum."];
 const g=allg[Math.floor(Date.now()/864e5)%allg.length];
 return`<div class="lsn-tipp"><small>LERNTIPP DER APP</small><p>${t}</p>${r0?bt(r0):""}<span>${g}</span></div>`;
}
async function lxLernstandSchueler(){
 const L=await lxMeinLaden(true);await lxTitelLaden().catch(()=>{});
 const T=lxMeineThemen(L);
 const ciV=id=>{const x=L.ci[id];return x?ciVerlauf(x):[]},coV=id=>{const x=L.ci[id+"@ende"];return x?ciVerlauf(x):[]};
 const rows=T.map(x=>{const a=ciV(x.e.id),b=coV(x.e.id);return{...x,ci:a.length?lsnPz(a[0]):null,co:b.length?lsnPz(b[b.length-1]):null,ciN:a.length,coN:b.length}});
 const nCi=rows.filter(r=>r.ciN).length,nCo=rows.filter(r=>r.coN).length,nUb=rows.reduce((s,r)=>s+r.m.ubN,0);
 const zu=rows.filter(r=>r.ci!=null&&r.co!=null).map(r=>r.co-r.ci),zm=zu.length?zu.reduce((s,v)=>s+v,0)/zu.length:null;
 const kachel=(z,t,u)=>`<div class="lsn-k"><b>${z}</b><span>${t}</span>${u?`<small>${u}</small>`:""}</div>`;
 const sum=`<div class="lsn-sum">${kachel(`${nCi} von ${rows.length}`,"Check-ins gemacht","Wo stehst du am Anfang?")}${kachel(`${nCo} von ${rows.length}`,"Check-outs gemacht","Was kannst du am Ende?")}${kachel(zm==null?"–":(zm>0?"+":"")+Math.round(zm*100)+" %","Lernzuwachs","Check-out minus Check-in")}${kachel(nUb,"Übungen bearbeitet","inklusive Vertiefungen")}</div>`;
 const lbs=[...new Set(rows.map(r=>r.ph.lbNum))].sort();
 const block=n=>{
  const R=rows.filter(r=>r.ph.lbNum===n);if(!R.length)return"";const ph=R[0].ph;
  return`<details class="lsn-lb lsn-lbd"><summary><header><small>LB ${n}</small><h3>${esc(ph.lbTitel||"")}</h3></header></summary>${R.map(r=>{
   const ub=L.ub.filter(u=>u.wocheId===r.e.id&&u.max>0),st={};ub.forEach(u=>{(st[u.stationId]=st[u.stationId]||[]).push(u)});
   const lis=Object.entries(st).map(([id,l])=>{l.sort((a,b)=>lxMs(a)-lxMs(b));const e=l[0],z=l[l.length-1];return`<li><span>${esc(lxUbTitel(id))}</span><em>${l.length} Versuch${l.length>1?"e":""}</em><b>${Math.round(e.punkte/e.max*100)} %${l.length>1?` → ${Math.round(z.punkte/z.max*100)} %`:""}</b></li>`}).join("");
   const fa=L.fa.filter(u=>u.wocheId===r.e.id&&u.max>0).map(u=>`<li><span>Fachaufsatz: ${esc((LXT.fa&&LXT.fa[u.aufsatzId||u.faId||u.stationId])||"Training")}</span><em>Selbsteinschätzung</em><b>${Math.round(u.punkte/u.max*100)} %</b></li>`).join("");
   return`<article class="lsn-t"><div class="lsn-th"><button type="button" class="text-button" data-kw="thema" data-id="${esc(r.e.id)}">${esc(lsThemaName(r.e.id))}</button><span>${r.m.ampel?lxPunkt(r.m.ampel,LX_AMP[r.m.ampel][1]):""}</span></div>
   <div class="lsn-m"><div><small>Check-in</small>${lsnBar(r.ci,"ci")}</div><div><small>Check-out</small>${lsnBar(r.co,"co")}</div><div><small>Zuwachs</small>${lsnZu(r.ci,r.co)}</div><div><small>Übungen</small>${r.m.ubN?`<b>${r.m.ubN} bearbeitet</b>`:`<span class="lsn-leer">–</span>`}</div><div><small>Selbsteinschätzung</small>${r.m.selbst?`<b>${["","noch unsicher","ein bisschen","ziemlich sicher","sicher"][r.m.selbst]}</b>`:`<span class="lsn-leer">–</span>`}</div></div>
   ${lis||fa?`<details><summary>Übungen und Vertiefungen anzeigen</summary><ul class="lsn-ul">${lis}${fa}</ul></details>`:""}</article>`}).join("")}</details>`;
 };
 const tipp=lxLerntipp(rows);
 return`<section class="lsn">${tipp}<div class="lsn-h"><small>MEINE LERNSTÄNDE</small><h2>Was bisher gemessen wurde</h2></div>${sum}${lbs.map(block).join("")}</section>`;
}
async function lxLernstandKlasse(){
 const K=await lxKlasseLaden(),N=K.schueler.length;
 const mean=a=>a.length?a.reduce((s,v)=>s+v,0)/a.length:null;
 const phs=LX_CFG.phasen().slice().sort((a,b)=>a.lbNum-b.lbNum);
 let sumCi=0,sumCo=0,nT=0;
 const block=ph=>{
  const R=kwThemenVonPhase(ph).map(e=>{
   const mm=K.schueler.map(u=>lxMetrik(u.uid,e.id,K)),mc=mm.filter(m=>m.c),mo=mm.filter(m=>m.ende);
   nT++;sumCi+=mc.length;sumCo+=mo.length;
   const ci=mean(mc.map(m=>m.wcErst)),co=mean(mo.map(m=>m.wcLetzt)),zu=mean(mo.map(m=>m.wcLetzt-m.wcErst));
   const ub=mm.filter(m=>m.ubN),ubq=mean(ub.map(m=>m.ubLetzt));
   const g={gruen:0,orange:0,rot:0};mm.forEach(m=>{if(m.ampel)g[m.ampel]++});
   return`<article class="lsn-t"><div class="lsn-th"><button type="button" class="text-button" data-ls="thema" data-id="${esc(e.id)}">${esc(lsThemaName(e.id))}</button><span class="lsn-amp"><i style="background:#2E7D57"></i>${g.gruen}<i style="background:#E0A800"></i>${g.orange}<i style="background:#C0392B"></i>${g.rot}</span></div>
   <div class="lsn-m"><div><small>Check-in (${mc.length}/${N})</small>${lsnBar(ci,"ci")}</div><div><small>Check-out (${mo.length}/${N})</small>${lsnBar(co,"co")}</div><div><small>Ø Zuwachs</small>${zu==null?`<span class="lsn-leer">–</span>`:`<b class="lsn-zu ${zu>0?"auf":"ab"}">${zu>0?"▲ +":"▼ "}${Math.round(zu*100)} %</b>`}</div><div><small>Übungen (${ub.length}/${N})</small>${lsnBar(ubq)}</div></div></article>`}).join("");
  return`<details class="lsn-lb lsn-lbd"><summary><header><small>LB ${ph.lbNum}</small><h3>${esc(ph.lbTitel||"")}</h3></header></summary>${R||`<div class="kw-leer">Keine Themen.</div>`}</details>`;
 };
 const bl=phs.map(block).join("");
 const kachel=(z,t,u)=>`<div class="lsn-k"><b>${z}</b><span>${t}</span>${u?`<small>${u}</small>`:""}</div>`;
 return`<section class="lsn"><div class="lsn-h"><small>KLASSENÜBERSICHT</small><h2>Check-in, Check-out und Übungen je Thema</h2></div><div class="lsn-sum">${kachel(N,"Schüler:innen")}${kachel(sumCi,"Check-ins abgegeben","über alle Themen")}${kachel(sumCo,"Check-outs abgegeben","über alle Themen")}${kachel(nT,"Themen")}</div>${bl}</section>`;
}
