async function renderLkPlanung(){
 if(!isTeacher())return await renderKachelwand();
 await kwLaden().catch(()=>{});await lxWaLaden(true);const ptSch=await lxPtSchuelerFeld();
 const dow=new Date().getDay(),mo=lxPlus(((1-dow+7)%7)||7),moD=new Date(mo+"T12:00:00"),addT=n=>{const d=new Date(moD);d.setDate(d.getDate()+n);return lxIso(d)};
 const tage=[0,1,2,3,4].map(addT),fr=tage[4],N=["Mo","Di","Mi","Do","Fr"];
 const phasen=[...LX_CFG.phasen()].sort((a,b)=>a.lbNum-b.lbNum);
 const fo=LXW_FAECHER.map(f=>`<option>${esc(f)}</option>`).join("");
 const WA=LXWA.d||[],PT=(LXWA.pt||[]).slice().sort((a,b)=>(a.zeit||"")<(b.zeit||"")?-1:1);
 const tag=iso=>{
  const t=PT.filter(x=>lxPtAn(x,iso)).map(x=>`<div class="lxs-ev"><small>${x.zeit?esc(lxZ(x))+" \u00B7 ":""}${esc(x.art||"")}${x.schuelerName?" \u00B7 "+esc(x.schuelerName):""}</small><b>${esc(x.titel||x.art||"")}</b><span class="lxp-a">${lxPtArbBtn(x)}<button type="button" class="secondary" data-wa="ptdel" data-id="${esc(x.id)}" title="Termin l\xF6schen">\u2715</button></span></div>`).join("");
  const a=WA.filter(w=>w.bis===iso).map(w=>`<div class="lxp-w">${(w.themen||[]).map(id=>{const e=kwThemaById(id);return e?`<div class="lxs-ev ab"><small>${esc(w.fach||"")} \u00B7 f\xE4llig</small><b>${esc(kwKurz(e))}</b><span class="lxp-a"><button type="button" class="secondary" data-kw="thema" data-id="${esc(id)}">Vorbereiten</button></span></div>`:""}).join("")}${(w.projekte||[]).map(n=>{const p=kwPhase(n);return p?`<div class="lxs-ev ab"><small>Projekt \u00B7 f\xE4llig</small><b>LB ${n} \u00B7 ${esc(p.titel||p.lbTitel||"")}</b><span class="lxp-a"><button type="button" class="secondary" data-kw="projekt" data-lb="${n}">Vorbereiten</button></span></div>`:""}).join("")}<div class="lxp-a"><button type="button" class="text-button" data-wa="del" data-id="${esc(w.id)}">Auftrag l\xF6schen</button></div></div>`).join("");
  return t+a||`<div class="lxs-frei">frei</div>`;
 };
 const themen=phasen.map(ph=>`<details class="lxw-lb" style="--c:${PP_FARBEN[ph.lbNum]||'#8a99a3'}"><summary><b>LB ${ph.lbNum} \u00B7 ${esc(ph.lbTitel||"")}</b></summary><div class="lxw-chips">${kwThemenVonPhase(ph).map(e=>`<label class="lxw-chip"><input type="checkbox" name="waThema" value="${esc(e.id)}"><span>${esc(kwKurz(e))}</span></label>`).join("")}</div></details>`).join("");
 const proj=phasen.map(ph=>`<label class="lxw-chip"><input type="checkbox" name="waProjekt" value="${ph.lbNum}"><span>Projekt LB ${ph.lbNum}</span></label>`).join("");
 return`<div class="lx-seite"><div class="kw-links"><button type="button" class="secondary" onclick="go('lk-unterricht')">\u2190 Meine Lernpfade</button></div>
 <h1 style="margin:8px 0 12px">N\xE4chste Woche \u00B7 ${fmtKurz(tage[0])}\u2013${fmtKurz(tage[4])}</h1>
 <div class="lxs-wt lxp-wt">${tage.map((iso,i)=>`<div class="lxs-d"><b>${N[i]} ${fmtKurz(iso)}</b>${tag(iso)}</div>`).join("")}</div>
 <details class="lxp-d"><summary>+ Themen oder Projekt einplanen</summary>
  <div class="lxw-row" style="margin-top:10px"><label>Fach<select id="waFach">${fo}</select></label><label>F\xE4llig bis<input type="date" id="waBis" value="${fr}"></label></div>
  <div class="lxw-sub"><b>Themen</b> <span id="waZahl" class="lxw-zahl">0 gew\xE4hlt</span></div>${themen}
  <div class="lxw-chips" style="margin-top:8px">${proj}</div>
  <div class="kw-aktionen"><button class="primary" data-wa="save">Einplanen</button></div></details>
 <details class="lxp-d"><summary>+ Termin ansetzen</summary>
  <div class="lxw-row" style="margin-top:10px"><label>Datum<input type="date" id="ptDatum" value="${mo}" min="${mo}" max="${fr}"></label><label>bis Datum (optional, mehrt\xE4gig)<input type="date" id="ptDatumBis" min="${mo}"></label></div><div class="lxw-row"><label>Uhrzeit von<input type="time" id="ptZeit"></label><label>bis (optional)<input type="time" id="ptZeitBis"></label></div>
  <label>Fach<select id="ptFach">${fo}</select></label>
  <label>Art<select id="ptArt"><option>Unterrichtsstunde</option><option>\xDCbung</option><option>Rollenspiel</option><option>Lernrallye</option><option>Selbstlernkurs</option><option>Fachaufsatztraining</option><option>K-Prim-Test</option><option>Projekt</option><option>Lernstandsgespr\xE4ch</option><option>Test</option><option>R\xFCckgabe Kurzarbeit/Schulaufgabe</option><option>Sonstiges</option></select></label>${ptSch}<div id="ptTrWrap" class="lxw-tr" hidden></div>
  <label>Verbindlichkeit<select id="ptPflicht"><option value="pflicht">Verpflichtend</option><option value="optional">Optional (freiwillig)</option></select></label>
  <label>Titel<input type="text" id="ptTitel" maxlength="90" placeholder="z. B. Projektstart LB 1"></label>
  <div class="kw-aktionen"><button class="primary" data-wa="ptsave">Termin ansetzen</button></div><div class="kw-aktionen" id="ptNeuWrap"><button type="button" class="secondary" data-wa="ptneu">Termin ansetzen und gleich erstellen</button></div></details>
 </div>${footer()}`;
}
