 const liste=gruppen.map(g=>`<div class="lx-tg" style="--k:${g.n?kwFarbe(g.n).c:"#64748b"}"><h4>${g.n?"Lernbereich "+g.n:"Weitere Tafeln"}</h4>${g.l.map(b=>zeile(b,g.n)).join("")}</div>`).join("");
