async function lbItemsSchreiben(boardId,items){
 const name=anzeigeName(profile,currentUser),jobs=[];
 items.forEach((teil,n)=>{
  const std=WB_STANDARD[teil.type]||{};
  const d={boardId,seite:1,c:std.c||"grau",fs:std.fs||18,z:Date.now()+n,authorUid:currentUser.uid,authorName:name,...std,...teil,createdAt:serverTimestamp(),updatedAt:serverTimestamp()};
  Object.keys(d).forEach(k=>{if(d[k]===undefined)delete d[k];});
  jobs.push(()=>setDoc(doc(collection(db,"whiteboardItems")),d));
 });
 for(let i=0;i<jobs.length;i+=20)await Promise.all(jobs.slice(i,i+20).map(f=>f()));
}
async function lbVorlageAnlegen(titel,beschr,beispiel){
 const r=await addDoc(collection(db,"whiteboards"),{title:(titel+" – Lernübersicht").slice(0,120),description:beschr,art:"tafel",schreibschutz:true,seiten:1,bg:"weiss",lernVorlage:true,createdBy:currentUser.uid,createdByName:anzeigeName(profile,currentUser),createdAt:serverTimestamp()});
 await lbItemsSchreiben(r.id,lbLernItems(0,0,titel,!!beispiel));
 return r.id;
}
// ---- Ordner „Lernübersichten“ (in den Lernressourcen) ----
async function lbOrdnerHtml(){
 try{
  const snap=await getDocs(query(collection(db,"whiteboards"),where("lernVorlage","==",true)));
  const liste=snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>(b.createdAt?.seconds||0)-(a.createdAt?.seconds||0));
  const lehrer=isTeacher();
  const meine=lehrer?{}:Object.fromEntries(await Promise.all(liste.map(async b=>{try{const s=await getDoc(doc(db,"ppLernuebersicht",b.id+"_"+currentUser.uid));return[b.id,s.exists()];}catch(e){return[b.id,false];}})));
  const karten=liste.map(b=>`<div style="position:relative"><button type="button" class="card" style="width:100%;height:100%;box-sizing:border-box;text-align:left;cursor:pointer;border-left:4px solid #2f7fc6;font:inherit${lehrer?";padding-right:52px":""}" onclick="lbOrdnerOeffnen('${esc(b.id)}')">
   <strong>${esc(String(b.title||"Lernübersicht").replace(/\s*–\s*Lernübersicht$/,""))}</strong><br>
   <small style="color:var(--muted)">${lehrer?"Vorlage öffnen und bearbeiten":(meine[b.id]?"Meine Kopie weiterbearbeiten ✓":"Eigene Kopie anlegen und ergänzen")}</small></button>${lehrer?`<button type="button" class="secondary" title="Lernübersicht löschen" aria-label="Lernübersicht löschen" style="position:absolute;top:8px;right:8px;min-height:36px;padding:0 10px" onclick="lbOrdnerLoeschen('${esc(b.id)}')">🗑</button>`:""}</div>`).join("");
  return`<section class="resource-section" id="lernuebersichten"><div class="section-head"><div><div class="kicker">📁 ORDNER</div><h2>Lernübersichten</h2></div><span class="pill">${liste.length}</span></div>
  <p style="color:var(--muted);margin:0 0 10px">Hier liegen alle Lernübersichten als Whiteboard. ${lehrer?"Du gestaltest sie, die Schüler:innen ergänzen sie in ihrer eigenen Kopie.":"Beim Öffnen bekommst du deine eigene Kopie: ergänze Notizen, Bilder und Zeichnungen und speichere sie als PDF."}</p>
  ${lehrer?`<div class="form-actions" style="margin:0 0 12px"><button type="button" class="secondary" onclick="lbOrdnerNeu(false)">＋ Neue Lernübersicht (5 Bausteine)</button><button type="button" class="secondary" onclick="lbOrdnerNeu(true)">＋ Beispiel: Starkes und schwaches Ich</button><button type="button" class="primary" onclick="lbBereitstellen()">⬇ Lernübersichten aus Datei bereitstellen</button></div>`:""}
  ${liste.length?`<div class="grid grid-3">${karten}</div>`:`<div class="card empty"><strong>Noch keine Lernübersicht.</strong><p>${lehrer?"Lege oben eine neue an oder hänge sie an eine Stunde bzw. ein Modul.":"Deine Lehrkraft legt sie nach und nach an."}</p></div>`}</section>`;
 }catch(err){console.warn("Ordner Lernübersichten:",err);return"";}
}
// ---- Lernübersicht löschen (Vorlage samt Schüler-Kopien und Verknüpfungen) ----
async function lbOrdnerLoeschen(id){
 if(!isTeacher())return;
 let kopien=[];
 try{kopien=(await getDocs(query(collection(db,"ppLernuebersicht"),where("lernId","==",id)))).docs;}catch(e){console.warn("Kopien lesen:",e);}
 if(!confirm("Diese Lernübersicht wirklich löschen?"+(kopien.length?"\n\nAuch die "+kopien.length+" Kopie"+(kopien.length===1?"":"n")+" der Schüler:innen mit deren Notizen werden gelöscht.":"")+"\n\nDas lässt sich nicht rückgängig machen."))return;
 const boardWeg=async bid=>{
  for(const c of["whiteboardItems","whiteboardImages","whiteboardPresence"]){
   const sn=await getDocs(query(collection(db,c),where("boardId","==",bid)));
   for(let i=0;i<sn.docs.length;i+=20)await Promise.all(sn.docs.slice(i,i+20).map(d=>deleteDoc(doc(db,c,d.id)).catch(()=>{})));
  }
  await deleteDoc(doc(db,"whiteboards",bid));
 };
 try{
  toast("Wird gelöscht …");
  for(const k of kopien){
   try{const bid=k.data().boardId;if(bid)await boardWeg(bid);}catch(e){console.warn("Kopie löschen:",e);}
   try{await deleteDoc(doc(db,"ppLernuebersicht",k.id));}catch(e){console.warn(e);}
  }
  try{
   const ml=await getDocs(query(collection(db,"ppModule"),where("lernBoardId","==",id)));
   await Promise.all(ml.docs.map(d=>updateDoc(doc(db,"ppModule",d.id),{lernBoardId:""})));
   if(ml.docs.length&&typeof ppmLaden==="function")await ppmLaden(true);
   const lw=await getDocs(query(collection(db,"lehrplanTafeln"),where("lernBoardId","==",id)));
   await Promise.all(lw.docs.map(d=>updateDoc(doc(db,"lehrplanTafeln",d.id),{lernBoardId:""})));
   lw.docs.forEach(d=>{if(typeof PP12_CACHE!=="undefined"&&PP12_CACHE.tafeln&&PP12_CACHE.tafeln[d.id])PP12_CACHE.tafeln[d.id].lernBoardId="";});
  }catch(e){console.warn("Verknüpfungen lösen:",e);}
  await boardWeg(id);
  await render();toast("Lernübersicht gelöscht.");
 }catch(err){
  console.error("Lernübersicht löschen:",err);
  toast(err?.code==="permission-denied"?"Firebase verweigert das Löschen. Bitte die Firestore-Regeln prüfen.":"Konnte nicht vollständig gelöscht werden.");
 }
}
// ---- Zuordnen: vorhandenen Roten Faden, eine Lernübersicht oder ein Whiteboard einer Stunde bzw. einem Modul zuweisen ----
const LB_Z_TABS=[["tafel","Roter Faden"],["lern","Lernübersicht"],["wb","Whiteboard"]];
function lbZFeld(tab){const q=(window.__lbZ||{}).q;return tab==="tafel"?(q==="z"?"boardId":"tafelId"):tab==="lern"?"lernBoardId":"whiteboardId";}
function lbZAktuell(tab){
 const z=window.__lbZ||{};
 const o=z.q==="z"?(PP12_CACHE.tafeln[z.ref]||{}):(ppmById(z.ref)||{});
 return o[lbZFeld(tab)]||"";
}
async function lbZuordnenDialog(q,ref,tab){
 if(!isTeacher())return;
 const lade=async w=>{const s=await getDocs(query(collection(db,"whiteboards"),w));return s.docs.map(d=>({id:d.id,...d.data()}));};
 const titel=b=>String(b.title||"Ohne Titel").replace(/\s*–\s*(Lernübersicht|Whiteboard)$/,"");
 const sort=l=>l.map(b=>({id:b.id,titel:titel(b)})).sort((x,y)=>x.titel.localeCompare(y.titel,"de"));
 let daten;
 try{
  const [t,l,w]=await Promise.all([lade(where("art","==","tafel")),lade(where("lernVorlage","==",true)),lade(where("art","==","team"))]);
  daten={tafel:sort(t.filter(b=>!b.lernVorlage)),lern:sort(l),wb:sort(w.filter(b=>!b.lernVorlage))};
 }catch(err){console.error("Zuordnen laden:",err);toast("Die Boards konnten nicht geladen werden.");return;}
 window.__lbZ={q,ref,tab:tab||"lern",daten};
 modal(`<button class="modal-close" onclick="closeModal()">×</button><div class="kicker">ZUORDNEN</div><h2>Zu ${q==="z"?"dieser Stunde":"diesem Modul"} zuordnen</h2>
  <p style="color:var(--muted);font-size:13px;margin:0 0 10px">Wähle zuerst die Art, dann das vorbereitete Board. Schüler:innen sehen es danach direkt hier.</p>
  <div id="lbZInner"></div>`);
 lbZRender();
}
function lbZRender(){
 const z=window.__lbZ,el=$("lbZInner");if(!z||!el)return;
 const tabs=LB_Z_TABS.filter(t=>t[0]!=="wb");const tab=z.tab,liste=z.daten[tab]||[],aktuell=lbZAktuell(tab),name=(LB_Z_TABS.find(t=>t[0]===tab)||[])[1];
 el.innerHTML=`<div style="display:flex;gap:6px;flex-wrap:wrap;margin:0 0 10px">${tabs.map(t=>{const n=lbZAktuell(t[0])?" ✓":"";return`<button type="button" class="${t[0]===tab?"primary":"secondary"}" onclick="lbZTab('${t[0]}')">${t[1]}${n} <small>(${z.daten[t[0]].length})</small></button>`}).join("")}</div>
  ${tab==="tafel"?`<div style="display:flex;gap:8px;flex-wrap:wrap;margin:0 0 10px"><button type="button" class="secondary" onclick="lbZRf('pdf')">📄 PDF anhängen</button><button type="button" class="secondary" onclick="lbZRf('web')">🌐 Webseite einbetten</button></div>`:""}
  ${tab==="lern"&&!aktuell?`<div style="display:flex;gap:8px;flex-wrap:wrap;margin:0 0 10px"><button type="button" class="secondary" onclick="lbZLernNeu()">＋ Neue leere Lernübersicht anlegen</button></div>`:""}
  <input type="search" placeholder="Suchen …" oninput="lbZFilter(this.value)" style="width:100%;box-sizing:border-box;min-height:40px;padding:0 12px;border:1px solid var(--line);border-radius:10px;font:inherit;margin:0 0 10px">
  <div id="lbZListe" style="display:grid;gap:8px;max-height:44vh;overflow:auto">${liste.map(b=>`<button type="button" class="secondary" data-t="${esc(b.titel.toLowerCase())}" style="text-align:left${b.id===aktuell?";border:2px solid #075a9d":""}" onclick="lbZuordnenSetzen('${esc(b.id)}')">${b.id===aktuell?"✓ ":""}${esc(b.titel)}</button>`).join("")||`<p class="ppm-leer">Noch kein vorbereitetes Board dieser Art vorhanden.</p>`}</div>
  <div class="form-actions" style="margin-top:12px">${aktuell?`<button class="secondary" type="button" onclick="lbZuordnenSetzen('')">${name} lösen</button>`:""}<button class="secondary" type="button" onclick="closeModal()">Schließen</button></div>`;
}
function lbZRf(art){const z=window.__lbZ;if(!z)return;window.__lbRf={q:z.q,ref:z.ref};if(art==="pdf")closeModal();lbRfWahl(art);}
async function lbZLernNeu(){
 const z=window.__lbZ;if(!z||!isTeacher())return;
 closeModal();window.__lbLernNeu=true;
 try{if(z.q==="z")await pp12Lern(z.ref);else{const m=ppmById(z.ref);if(m)await lbModulLern(m);}}
 finally{window.__lbLernNeu=false;}
}
function lbZTab(tab){if(window.__lbZ){window.__lbZ.tab=tab;lbZRender();}}
function lbZFilter(v){
 const t=String(v||"").trim().toLowerCase();
 document.querySelectorAll("#lbZListe [data-t]").forEach(b=>{b.style.display=!t||b.dataset.t.includes(t)?"":"none";});
}
