// ---- Roter Faden (Modul oder Zeitstrahl-Stunde): digitale Tafel, PDF oder eingebettete Webseite ----
// q "m" = Modul (ppModule), q "z" = Stunde im Zeitstrahl (lehrplanTafeln, Schlüssel = Datum)
function lbRfObj(q,ref){return q==="z"?((typeof PP12_CACHE!=="undefined"&&PP12_CACHE.tafeln[ref])||{}):(ppmById(ref)||{});}
function lbRfTitelFuer(q,ref){return q==="z"?lbStundeTitel(ref):lbModulTitel(ppmById(ref)||{});}
async function lbRfSpeichern(e,t,n){e==="z"?(await setDoc(doc(db,"lehrplanTafeln",t),n,{merge:!0}),PP12_CACHE.tafeln[t]={...PP12_CACHE.tafeln[t]||{},...n}):(await updateDoc(doc(db,"ppModule",t),n),await ppmLaden(!0))}
async function lbModulTafel(m){
 if(m.rfUrl){lbRfOeffnen(m);return;}
 if(m.tafelId){openWhiteboard(m.tafelId);return;}
 if(!isTeacher())return;
 lbRfDialog("m",m.id);
}
function lbRfDialog(q,ref){
 if(!isTeacher())return;
 window.__lbRf={q,ref};
 modal(`<button class="modal-close" onclick="closeModal()">×</button><div class="kicker">ROTER FADEN</div><h2>Was soll der Rote Faden sein?</h2>
  <p style="color:var(--muted);font-size:13px">Schüler:innen können ihn nur ansehen, nicht verändern.</p>
  <div style="display:grid;gap:8px">
   <button type="button" class="secondary" style="text-align:left" onclick="lbRfWahl('tafel')">▦ Digitale Tafel anlegen</button>
   <button type="button" class="secondary" style="text-align:left" onclick="lbRfWahl('pdf')">📄 PDF anhängen</button>
   <button type="button" class="secondary" style="text-align:left" onclick="lbRfWahl('web')">🌐 Webseite einbetten</button>
  </div>
  <div class="form-actions" style="margin-top:12px"><button class="secondary" type="button" onclick="closeModal()">Abbrechen</button></div>`);
}
async function lbRfWahl(art){
 const r0=window.__lbRf;if(!r0||!isTeacher())return;
 const q=r0.q,ref=r0.ref;
 try{
  if(art==="tafel"){
   closeModal();
   if(q==="z"){window.__lbRfDirekt=true;await pp12Tafel(ref);await render();return;}
   const m=ppmById(ref);
   const t=await ppmTafelAnlegen(lbModulTitel(m));
   await lbRfAlteWeg(m);
   await lbRfSpeichern("m",ref,{tafelId:t,rfTyp:"",rfUrl:"",rfTitel:""});await render();openWhiteboard(t);return;
  }
  if(art==="pdf"){
   const inp=document.createElement("input");inp.type="file";inp.accept="application/pdf,.pdf";
   inp.onchange=async()=>{
    const f=inp.files&&inp.files[0];if(!f)return;
    if(!/pdf/i.test(f.type)&&!/\.pdf$/i.test(f.name)){toast("Bitte eine PDF-Datei wählen.");return;}
    try{
     closeModal();toast("PDF wird hochgeladen …");
     const r=await uploadCampusDatei(f,"whiteboardDateien/"+(q==="z"?"tag_":"modul_")+ref);
     await lbRfAlteWeg(lbRfObj(q,ref));
     await lbRfSpeichern(q,ref,q==="z"?{rfTyp:"pdf",rfUrl:r.url,rfTitel:f.name.replace(/\.pdf$/i,"").slice(0,120),boardId:""}:{rfTyp:"pdf",rfUrl:r.url,rfTitel:f.name.replace(/\.pdf$/i,"").slice(0,120),tafelId:""});
     await render();toast("PDF als Roter Faden angehängt.");
    }catch(err){console.error("Roter Faden PDF:",err);toast(err&&err.message?err.message:"Das PDF konnte nicht angehängt werden.");}
   };
   inp.click();return;
  }
  if(art==="web"){
   modal(`<button class="modal-close" onclick="closeModal()">×</button><div class="kicker">ROTER FADEN</div><h2>Webseite einbetten</h2>
    <p style="color:var(--muted);font-size:13px">Du kannst die Adresse oder den kompletten iframe-Code einfügen (z. B. von fobizz, padlet, Canva, YouTube). Manche Seiten erlauben das Einbetten nicht; dann bleibt der Rahmen leer, und der Knopf „In neuem Tab“ hilft.</p>
    <label style="display:block;margin:0 0 8px">Adresse oder iframe-Code<input id="lbRfUrl" type="text" autocomplete="off" style="width:100%;box-sizing:border-box;min-height:42px;padding:0 12px;border:1px solid var(--line);border-radius:10px;font:inherit"></label>
    <label style="display:block;margin:0 0 8px">Titel (optional)<input id="lbRfTitel" type="text" maxlength="120" style="width:100%;box-sizing:border-box;min-height:42px;padding:0 12px;border:1px solid var(--line);border-radius:10px;font:inherit"></label>
    <div class="form-actions" style="margin-top:12px"><button class="primary" type="button" onclick="lbRfWebSpeichern()">Speichern</button><button class="secondary" type="button" onclick="closeModal()">Abbrechen</button></div>`);
  }
 }catch(err){console.error("Roter Faden:",err);toast(err&&err.message?err.message:"Das hat nicht geklappt.");}
}
async function lbRfWebSpeichern(){
 const r0=window.__lbRf;if(!r0||!isTeacher())return;
 const q=r0.q,ref=r0.ref;
 let roh=String(($("lbRfUrl")||{}).value||"").trim();
 const fm=roh.match(/<iframe[^>]*?\ssrc\s*=\s*["']([^"']+)["']/i);if(fm)roh=fm[1].replace(/&amp;/g,"&").trim();
 const url=wbEmbedUrl(roh);
 if(!url){toast("Bitte eine gültige Adresse (https://…) eingeben.");return;}
 const titel=String(($("lbRfTitel")||{}).value||"").trim().slice(0,120)||"Webseite";
 try{
  await lbRfAlteWeg(lbRfObj(q,ref));
  await lbRfSpeichern(q,ref,q==="z"?{rfTyp:"web",rfUrl:url,rfTitel:titel,boardId:""}:{rfTyp:"web",rfUrl:url,rfTitel:titel,tafelId:""});
  closeModal();await render();toast("Webseite als Roter Faden eingebettet.");
 }catch(err){
  console.error("Roter Faden Webseite:",err);
  toast(err?.code==="permission-denied"?"Firebase verweigert das Speichern. Bitte die Firestore-Regeln prüfen.":"Das hat nicht geklappt.");
 }
}
// Ein früher hochgeladenes PDF wird beim Ersetzen aus dem Speicher entfernt (die Tafel selbst bleibt immer bestehen).
async function lbRfAlteWeg(m){if(m&&m.rfTyp==="pdf"&&m.rfUrl){try{await deleteCampusDatei(m.rfUrl);}catch(e){}}}
function lbRfOeffnen(m){
 lbRfSchliessen();
 const pdf=m.rfTyp==="pdf",src=pdf?m.rfUrl:wbEmbedUrl(m.rfUrl);
 if(!src){toast("Der Rote Faden hat keine gültige Adresse.");return;}
 window.__lbRfUrl=src;
 const ov=document.createElement("div");ov.id="lbRfOverlay";ov.className="exp-overlay";
 ov.innerHTML=`<div class="exp-leiste"><b>${pdf?"📄":"🌐"} ${esc(m.rfTitel||"Roter Faden")}</b><span style="display:flex;gap:8px"><button type="button" class="secondary" onclick="lbRfNeuerTab()">↗ In neuem Tab</button><button type="button" class="secondary" onclick="lbRfSchliessen()">✕ Schließen</button></span></div><iframe title="${esc(m.rfTitel||"Roter Faden")}" src="${esc(src)}"${pdf?"":` sandbox="${wbEmbedSandbox(src)}" allow="fullscreen" allowfullscreen`}></iframe>`;
 document.body.appendChild(ov);document.body.classList.add("exp-offen");
}
function lbRfSchliessen(){const o=document.getElementById("lbRfOverlay");if(o)o.remove();document.body.classList.remove("exp-offen");}
function lbRfNeuerTab(){if(window.__lbRfUrl)window.open(window.__lbRfUrl,"_blank","noopener");}
async function lbModulWb(m){
 if(m.whiteboardId){openWhiteboard(m.whiteboardId);return;}
 if(!isTeacher())return;
 const r=await addDoc(collection(db,"whiteboards"),{title:(lbModulTitel(m)+" – Whiteboard").slice(0,120),description:"Gemeinsames Whiteboard zum Modul",art:"team",schreibschutz:false,seiten:1,bg:"weiss",createdBy:currentUser.uid,createdByName:anzeigeName(profile,currentUser),createdAt:serverTimestamp()});
 await updateDoc(doc(db,"ppModule",m.id),{whiteboardId:r.id});await ppmLaden(true);openWhiteboard(r.id);
}
async function lbModulLern(m){
 if(m.lernBoardId){
  if(isTeacher()){openWhiteboard(m.lernBoardId);return;}
  await lbMeineKopie(m.lernBoardId,lbModulTitel(m));return;
 }
 if(!isTeacher())return;
 if(!window.__lbLernNeu){await lbZuordnenDialog("m",m.id,"lern");return;}
 const id=await lbVorlageAnlegen(lbModulTitel(m),"Lernübersicht zum Modul: Zusammenfassung der Lehrkraft, Schüler:innen bekommen eine eigene Kopie zum Ergänzen");
 await updateDoc(doc(db,"ppModule",m.id),{lernBoardId:id});await ppmLaden(true);openWhiteboard(id);
}
// ---- Whiteboard als PDF (Druckdialog „Als PDF sichern“) ----
function wbPdfFenster(cv){
 const win=window.open("","_blank");
 if(!win){toast("Bitte Pop-ups für diese Seite erlauben.");return}
 const t=String(wb&&wb.board&&wb.board.title||"Whiteboard").replace(/&/g,"&amp;").replace(/</g,"&lt;");
 win.document.write(`<!doctype html><html lang="de"><head><meta charset="utf-8"><title>${t}</title><style>@page{size:A4 ${cv.width>cv.height?"landscape":"portrait"};margin:10mm}body{margin:0;font-family:Arial,sans-serif}h1{font-size:15px;margin:0 0 6px}img{max-width:100%;max-height:calc(100vh - 40px);display:block}.n{background:#f3f3f3;padding:8px;border-radius:6px;margin-bottom:10px;font-size:11px}@media print{.n{display:none}img{max-height:none}}</style></head><body><div class="n">Im Druckdialog „Als PDF sichern“ bzw. „PDF“ auswählen. Gedruckt wird die aktuelle Seite des Whiteboards.</div><h1>${t}</h1><img src="${cv.toDataURL("image/png")}" alt=""><script>window.onload=function(){setTimeout(function(){window.print()},400)}<\/script></body></html>`);
 win.document.close();
}
async function wbExportPdf(){
 if(!wb)return;
 wb.pdfModus=true;
 try{await wbExport();}finally{wb.pdfModus=false;}
}
Object.assign(window,{pp12Lern:typeof pp12Lern==="function"?pp12Lern:undefined,pp12Wb:typeof pp12Wb==="function"?pp12Wb:undefined,lbOrdnerOeffnen,lbOrdnerNeu,lbBereitstellen,lbOrdnerLoeschen,lbZuordnenDialog,lbZuordnenSetzen,lbZFilter,lbZTab,lbZLernNeu,lbZRf,lbRfDialog,lbRfWahl,lbRfWebSpeichern,lbRfOeffnen,lbRfSchliessen,lbRfNeuerTab,pp12LernZuordnen,lbLoesenDialog,lbLoesen,pp12Loesen});

/* Ladestabilität (iPhone/iPad): fehlgeschlagene Ladeversuche werden wiederholt, nicht dauerhaft gemerkt */
function ladeWarte(ms){return new Promise(r=>setTimeout(r,ms))}
let sichtbarSeit=Date.now();
document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible")sichtbarSeit=Date.now()});
window.addEventListener("pageshow",()=>{sichtbarSeit=Date.now()});
async function fbImportMitWiederholung(url){
 let letzter;
 for(let v=0;v<4;v++){
  try{
   const m=await import(v?url+"&r="+v+Date.now().toString(36):url);
   if(window.__bootMsg)window.__bootMsg("");
   return m;
  }catch(e){
   letzter=e;console.warn("Firebase laden, Versuch "+(v+1)+":",e);
   if(v<3){if(window.__bootMsg)window.__bootMsg("Die Verbindung hakt. Neuer Versuch "+(v+1)+" von 3 …");await ladeWarte(900*(v+1))}
  }
 }
 throw letzter;
}
function fsLeseMitWiederholung(fn){
 return async(...args)=>{
  /* iOS bricht Anfragen direkt nach dem Zurückkehren zur Seite oft ab: kurz warten */
  const w=400-(Date.now()-sichtbarSeit);if(w>0)await ladeWarte(w);
  let letzter;
  for(let i=0;i<3;i++){
   try{return await fn(...args)}catch(e){
    letzter=e;const c=String(e&&e.code||"");
    if(c==="permission-denied"||c==="not-found"||c==="invalid-argument"||c==="unauthenticated"||c==="failed-precondition")throw e;
    if(i<2)await ladeWarte(600*(i+1));
   }
  }
  throw letzter;
 };
}

window.__booted=1,window.__bootOk&&window.__bootOk()

